	bonusBoundaryWhite = scoreMatch / 2
	bonusBoundary      = scoreMatch/4 + 1
	bonusCamel123      = bonusBoundary + 2
	bonusConsecutive   = -(scoreGapStart + scoreGapExtension)
	bonusFirstCharMultiplier = 2
