	}
	if r == '/' || r == '\\' || r == '-' || r == '_' || r == '.' || r == ',' {
		return charDelimiter
	}
	return charNonWord
}

// bonusFor calculates the bonus for a character at position given the previous character class
func bonusFor(prevClass, class charClass) int32 {
	if class > charNonWord {
		if prevClass == charNonWord {
			// Word boundary
			return bonusBoundaryWhite
		}
		if prevClass == charDelimiter {
			return bonusBoundary
		}
		if prevClass == charLower && class == charUpper {
			return bonusCamel123
		}
		if prevClass == charLetter && class == charNumber {
			return bonusCamel123
		}
		if prevClass == charNumber && class == charLetter {
			return bonusCamel123
		}
	}
	return 0
}

