	copy(T, text)
	P := make([]rune, M)
	copy(P, pattern)

	if !caseSensitive {
		for i, r := range T {
			T[i] = unicode.ToLower(r)
		}
		for i, r := range P {
			P[i] = unicode.ToLower(r)
		}
	}
