	textClass := make([]charClass, N)
	for i, r := range text {
		textClass[i] = charClassOf(r)
	}

	// Precompute bonuses for each position in text
	bonus := make([]int32, N)
	prevClass := charDelimiter // assume non-word before start
	for i, class := range textClass {
		bonus[i] = int32(bonusFor(prevClass, class))
		prevClass = class
	}

