	// Simple Smith-Waterman-like algorithm

	// Find first occurrence of last pattern char to limit search
	// Use DP approach

	H := make([]int32, N)
	C := make([]int32, N)
	F := make([]int32, M)

	maxScore := int32(0)
	maxScoreEnd := 0

	// For each pattern char, compute scores
	for i := 0; i < M; i++ {
		p := P[i]
		newH := make([]int32, N)
		newC := make([]int32, N)

