			t := T[j]
			if t == p {
				var score int32
				if i == 0 {
					score = int32(scoreMatch) + bonus[j]*int32(bonusFirstCharMultiplier)
				} else {
					score = int32(scoreMatch) + bonus[j]
				}

				// Add consecutive bonus or gap penalty
				if i > 0 {
					if j > 0 && H[j-1] > 0 {
