				if i > 0 && j > 0 {
					newC[j] = C[j-1] + bonus[j]
					if newC[j] < 0 {
						newC[j] = 0
					}
				}

				if i == M-1 && score > maxScore {
					maxScore = score
					maxScoreEnd = j
				}

				if i == 0 {
					F[0] = max32(F[0], score)
				} else {
					F[i] = max32(F[i], score)
				}
			}
		}

		H = newH
		C = newC
	}

