func max32(a, b int32) int32 {
	if a > b {
		return a
	}
	return b
}

// fuzzyMatchV2Simple is a simpler but correct implementation
func fuzzyMatchV2Simple(caseSensitive bool, normalize bool, forward bool, text []rune, pattern []rune, withPos bool) (Result, *[]int) {
	M := len(pattern)
	if M == 0 {
		return Result{0, 0, 0}, &[]int{}
	}
	N := len(text)
	if N == 0 {
		return Result{-1, -1, 0}, nil
	}

	// Build comparable versions
	T := make([]rune, N)
	copy(T, text)
	P := make([]rune, M)
	copy(P, pattern)

	if !caseSensitive {
		for i, r := range T {
			T[i] = unicode.ToLower(r)
		}
		for i, r := range P {
			P[i] = unicode.ToLower(r)
		}
	}
	if normalize {
		for i, r := range T {
			T[i] = normalizeRune(r)
		}
		for i, r := range P {
			P[i] = normalizeRune(r)
		}
	}

	// Find first fuzzy match
	pidx := 0
	sidx := -1
	eidx := -1
	dir := 1
	start := 0
	end := N - 1
	if !forward {
		dir = -1
		start = N - 1
		end = 0
	}

	for i := start; i != end+dir; i += dir {
		if T[i] == P[pidx] {
			if pidx == 0 {
				sidx = i
			}
			pidx++
			if pidx == M {
				eidx = i + 1
				break
			}
		}
	}

	if eidx < 0 {
		return Result{-1, -1, 0}, nil
	}

	// Calculate score
	score := calculateScore(text, T, pattern, P, sidx, eidx, caseSensitive, normalize)

	var positions *[]int
	if withPos {
		pos := findPositions(T, P, sidx, eidx)
		positions = &pos
	}

	return Result{sidx, eidx, score}, positions
}

func findPositions(T, P []rune, sidx, eidx int) []int {
	M := len(P)
	positions := make([]int, M)
	pidx := M - 1
	for i := eidx - 1; i >= sidx && pidx >= 0; i-- {
		if T[i] == P[pidx] {
			positions[pidx] = i
			pidx--
		}
	}
	return positions
}

func calculateScore(origText []rune, T []rune, origPattern []rune, P []rune, sidx, eidx int, caseSensitive bool, normalize bool) int {
	score := 0
	M := len(P)
	N := len(origText)

	// Compute character classes for text
	textClass := make([]charClass, N)
	prevClass := charDelimiter
	for i, r := range origText {
		textClass[i] = charClassOf(r)
		_ = r
		prevClass = textClass[i]
		_ = prevClass
	}

	// Precompute bonuses
	bonuses := make([]int32, N)
	prevClass = charDelimiter
	for i, class := range textClass {
		bonuses[i] = int32(bonusFor(prevClass, class))
		prevClass = class
	}

	pidx := 0
	inGap := false
	consecutive := 0

	for i := sidx; i < eidx && pidx < M; i++ {
		if T[i] == P[pidx] {
			score += scoreMatch
			score += int(bonuses[i])
			if pidx == 0 {
				score += int(bonuses[i]) * (bonusFirstCharMultiplier - 1)
			}
			if consecutive > 0 {
				score += bonusConsecutive
			}
			consecutive++
			inGap = false
			pidx++
		} else {
			if !inGap {
				score += scoreGapStart
				inGap = true
			} else {
				score += scoreGapExtension
			}
			consecutive = 0
		}
	}

	return score
}

// Slab is used for memory reuse
type Slab struct {
	I16 []int16
	I32 []int32
}

// ExactMatchNaive checks if pattern is a substring of text
func ExactMatchNaive(caseSensitive bool, normalize bool, forward bool, text []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	M := len(pattern)
	if M == 0 {
		return Result{0, 0, 0}, &[]int{}
	}
	N := len(text)
	if N < M {
		return Result{-1, -1, 0}, nil
	}

	T := make([]rune, N)
	copy(T, text)
	P := make([]rune, M)
	copy(P, pattern)

	if !caseSensitive {
		for i, r := range T {
			T[i] = unicode.ToLower(r)
		}
		for i, r := range P {
			P[i] = unicode.ToLower(r)
		}
	}
	if normalize {
		for i, r := range T {
			T[i] = normalizeRune(r)
		}
		for i, r := range P {
			P[i] = normalizeRune(r)
		}
	}

	dirs := []int{1}
	if !forward {
		dirs = []int{-1}
	}

	for _, dir := range dirs {
		start := 0
		end := N - M
		if dir < 0 {
			start = N - M
			end = 0
		}
		for i := start; ; i += dir {
			match := true
			for j := 0; j < M; j++ {
				if T[i+j] != P[j] {
					match = false
					break
				}
			}
			if match {
				score := calculateScore(text, T, pattern, P, i, i+M, caseSensitive, normalize)
				var positions *[]int
				if withPos {
					pos := make([]int, M)
					for j := 0; j < M; j++ {
						pos[j] = i + j
					}
					positions = &pos
				}
				return Result{i, i + M, score}, positions
			}
			if i == end {
				break
			}
		}
	}

	return Result{-1, -1, 0}, nil
}

// PrefixMatch checks if pattern is a prefix of text
func PrefixMatch(caseSensitive bool, normalize bool, forward bool, text []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	M := len(pattern)
	if M == 0 {
		return Result{0, 0, 0}, &[]int{}
	}
	N := len(text)
	if N < M {
		return Result{-1, -1, 0}, nil
	}

	T := make([]rune, N)
	copy(T, text)
	P := make([]rune, M)
	copy(P, pattern)

	if !caseSensitive {
		for i, r := range T {
			T[i] = unicode.ToLower(r)
		}
		for i, r := range P {
			P[i] = unicode.ToLower(r)
		}
	}
	if normalize {
		for i, r := range T {
			T[i] = normalizeRune(r)
		}
		for i, r := range P {
			P[i] = normalizeRune(r)
		}
	}

	for j := 0; j < M; j++ {
		if T[j] != P[j] {
			return Result{-1, -1, 0}, nil
		}
	}

	score := calculateScore(text, T, pattern, P, 0, M, caseSensitive, normalize)
	var positions *[]int
	if withPos {
		pos := make([]int, M)
		for j := 0; j < M; j++ {
			pos[j] = j
		}
		positions = &pos
	}
	return Result{0, M, score}, positions
}

// SuffixMatch checks if pattern is a suffix of text
func SuffixMatch(caseSensitive bool, normalize bool, forward bool, text []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	M := len(pattern)
	if M == 0 {
		return Result{0, 0, 0}, &[]int{}
	}
	N := len(text)
	if N < M {
		return Result{-1, -1, 0}, nil
	}

	T := make([]rune, N)
	copy(T, text)
	P := make([]rune, M)
	copy(P, pattern)

	if !caseSensitive {
		for i, r := range T {
			T[i] = unicode.ToLower(r)
		}
		for i, r := range P {
			P[i] = unicode.ToLower(r)
		}
	}
	if normalize {
		for i, r := range T {
			T[i] = normalizeRune(r)
		}
		for i, r := range P {
			P[i] = normalizeRune(r)
		}
	}

	offset := N - M
	for j := 0; j < M; j++ {
		if T[offset+j] != P[j] {
			return Result{-1, -1, 0}, nil
		}
	}

	score := calculateScore(text, T, pattern, P, offset, N, caseSensitive, normalize)
	var positions *[]int
	if withPos {
		pos := make([]int, M)
		for j := 0; j < M; j++ {
			pos[j] = offset + j
		}
		positions = &pos
	}
	return Result{offset, N, score}, positions
}

// EqualMatch checks for exact equality
func EqualMatch(caseSensitive bool, normalize bool, forward bool, text []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	M := len(pattern)
	N := len(text)
	if M != N {
		return Result{-1, -1, 0}, nil
	}
	return ExactMatchNaive(caseSensitive, normalize, forward, text, pattern, withPos, slab)
}

// normalizeRune normalizes latin script letters
func normalizeRune(r rune) rune {
	if r < 0x00C0 {
		return r
	}
	// Map accented characters to their base
	switch {
	case r >= 0x00C0 && r <= 0x00C5: return 'A'
	case r == 0x00C6: return 'A' // Æ - simplified
	case r == 0x00C7: return 'C'
	case r >= 0x00C8 && r <= 0x00CB: return 'E'
	case r >= 0x00CC && r <= 0x00CF: return 'I'
	case r == 0x00D0: return 'D'
	case r == 0x00D1: return 'N'
	case r >= 0x00D2 && r <= 0x00D6: return 'O'
	case r == 0x00D8: return 'O'
	case r >= 0x00D9 && r <= 0x00DC: return 'U'
	case r == 0x00DD: return 'Y'
	case r == 0x00DE: return 'T'
	case r == 0x00DF: return 's'
	case r >= 0x00E0 && r <= 0x00E5: return 'a'
	case r == 0x00E6: return 'a'
	case r == 0x00E7: return 'c'
	case r >= 0x00E8 && r <= 0x00EB: return 'e'
	case r >= 0x00EC && r <= 0x00EF: return 'i'
	case r == 0x00F0: return 'd'
	case r == 0x00F1: return 'n'
	case r >= 0x00F2 && r <= 0x00F6: return 'o'
	case r == 0x00F8: return 'o'
	case r >= 0x00F9 && r <= 0x00FC: return 'u'
	case r == 0x00FD: return 'y'
	case r == 0x00FE: return 't'
	case r == 0x00FF: return 'y'
	}
	return r
}

// RunesToChars converts a string to rune slice
func RunesToChars(s string) []rune {
	return []rune(s)
}

// BytesToChars converts a byte slice to rune slice
func BytesToChars(b []byte) []rune {
	return []rune(string(b))
}

// Dummy use of utf8
var _ = utf8.RuneLen
GOEOF
echo "Written algo.go"

