func bonusFor(prevClass, class charClass) int32 {
	if class > charNonWord {
		switch prevClass {
		case charDelimiter:
			return bonusBoundaryWhite
		case charNonWord:
			return bonusBoundary
		case charLower:
			if class == charUpper {
				return bonusCamel123
			}
		case charUpper:
			// Upper after upper (like "AB") - no extra bonus
		case charNumber:
			if class == charLetter || class == charUpper || class == charLower {
