// ExactMatchNaive finds exact substring match
func ExactMatchNaive(caseSensitive, normalize, forward bool, input []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	M := len(pattern)
	if M == 0 {
		return Result{0, 0, 0}, &[]int{}
	}
	N := len(input)
	if N < M {
		return Result{-1, -1, 0}, nil
	}

	T := prepareRunes(input, caseSensitive, normalize)
	P := prepareRunes(pattern, caseSensitive, normalize)

	// Precompute bonus
	bonus := make([]int32, N)
	bonus[0] = bonusBoundaryWhite
	for i := 1; i < N; i++ {
		bonus[i] = bonusFor(charClassOf(input[i-1]), charClassOf(input[i]))
	}

	search := func(start, end, dir int) (int, int) {
		for i := start; ; i += dir {
			match := true
			for j := 0; j < M; j++ {
				if T[i+j] != P[j] {
					match = false
					break
				}
			}
			if match {
				return i, i + M
			}
			if i == end {
				break
			}
		}
		return -1, -1
	}

	var sidx, eidx int
	if forward {
		sidx, eidx = search(0, N-M, 1)
	} else {
		sidx, eidx = search(N-M, 0, -1)
	}

	if sidx < 0 {
		return Result{-1, -1, 0}, nil
	}

	// Calculate score
	score := scoreMatch + int(bonus[sidx])*bonusFirstCharMultiplier
	prev := sidx
	_ = prev
	consecutive := 1
	for j := sidx + 1; j < eidx; j++ {
		var consBonus int32
		if bonus[j] > int32(bonusConsecutive) {
			consBonus = bonus[j]
		} else {
			consBonus = int32(bonusConsecutive)
		}
		_ = consecutive
		score += scoreMatch + int(consBonus)
		consecutive++
	}

	var positions *[]int
	if withPos {
		pos := make([]int, M)
		for j := 0; j < M; j++ {
			pos[j] = sidx + j
		}
		positions = &pos
	}
	return Result{sidx, eidx, score}, positions
}

// PrefixMatch checks if text starts with pattern
func PrefixMatch(caseSensitive, normalize, forward bool, input []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	M := len(pattern)
	if M == 0 {
		return Result{0, 0, 0}, &[]int{}
	}
	N := len(input)
	if N < M {
		return Result{-1, -1, 0}, nil
	}

	T := prepareRunes(input, caseSensitive, normalize)
	P := prepareRunes(pattern, caseSensitive, normalize)

	for j := 0; j < M; j++ {
		if T[j] != P[j] {
			return Result{-1, -1, 0}, nil
		}
	}
	return ExactMatchNaive(caseSensitive, normalize, true, input, pattern[:M], withPos, slab)
}

// SuffixMatch checks if text ends with pattern
func SuffixMatch(caseSensitive, normalize, forward bool, input []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	M := len(pattern)
	if M == 0 {
		return Result{0, 0, 0}, &[]int{}
	}
	N := len(input)
	if N < M {
		return Result{-1, -1, 0}, nil
	}

	T := prepareRunes(input, caseSensitive, normalize)
	P := prepareRunes(pattern, caseSensitive, normalize)

	offset := N - M
	for j := 0; j < M; j++ {
		if T[offset+j] != P[j] {
			return Result{-1, -1, 0}, nil
		}
	}
	return ExactMatchNaive(caseSensitive, normalize, false, input, pattern, withPos, slab)
}

// EqualMatch checks for exact equality
func EqualMatch(caseSensitive, normalize, forward bool, input []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	if len(input) != len(pattern) {
		return Result{-1, -1, 0}, nil
	}
	return ExactMatchNaive(caseSensitive, normalize, true, input, pattern, withPos, slab)
}
