	}
	N := len(text)
	if N == 0 || M > N {
		return Result{-1, -1, 0}, nil
	}

	T := trimText(text, caseSensitive, normalize)
	P := trimText(pattern, caseSensitive, normalize)

	// Precompute bonuses for each position
	bonus := make([]int32, N)
	bonus[0] = bonusBoundaryWhite
	for i := 1; i < N; i++ {
		bonus[i] = bonusFor(charClassOf(text[i-1]), charClassOf(text[i]))
	}

