				b := bonus[j]
				bestScore := int32(-1 << 30)

				// Option 1: consecutive match from j-1
				if j > 0 && H[j-1].score > 0 {
					prevB := H[j-1].bonus
					// Consecutive bonus: max(bonusConsecutive, prevBonus)
					consBonus := int32(bonusConsecutive)
					if prevB > consBonus {
						consBonus = prevB
					}
					s := H[j-1].score + int32(scoreMatch) + consBonus
					if s > bestScore {
						bestScore = s
						b = consBonus // update bonus for propagation
					}
				}

