				// Use the running max from previous row with gap penalty
				for k := 0; k < j-1; k++ {
					if H[k].score > 0 {
						gap := int32(j - k - 1)
						gapPenalty := int32(scoreGapStart) + int32(scoreGapExtension)*gap
						s := H[k].score + gapPenalty + int32(scoreMatch) + bonus[j]
						if s > bestScore {
