	end := bestEnd + 1

	var posResult *[]int
	if withPos {
		posResult = &positions
	}

	return Result{start, end, int(bestScore)}, posResult
}

// FuzzyMatchV1 implements the v1 greedy fuzzy matching algorithm
func FuzzyMatchV1(caseSensitive, normalize, forward bool, text []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	M := len(pattern)
	if M == 0 {
		return Result{0, 0, 0}, &[]int{}
	}
	N := len(text)
	if N == 0 || M > N {
		return Result{-1, -1, 0}, nil
	}

	T := trimText(text, caseSensitive, normalize)
	P := trimText(pattern, caseSensitive, normalize)

	bonus := make([]int32, N)
	bonus[0] = bonusBoundaryWhite
	for i := 1; i < N; i++ {
		bonus[i] = bonusFor(charClassOf(text[i-1]), charClassOf(text[i]))
	}

	sidx := -1
	eidx := -1
	pidx := 0

	if forward {
		for j := 0; j < N; j++ {
			if T[j] == P[pidx] {
				if pidx == 0 {
					sidx = j
				}
				pidx++
				if pidx == M {
					eidx = j + 1
					break
				}
			}
		}
	} else {
		pidx = M - 1
		for j := N - 1; j >= 0; j-- {
			if T[j] == P[pidx] {
				if pidx == M-1 {
					eidx = j + 1
				}
				pidx--
				if pidx < 0 {
					sidx = j
					break
				}
			}
		}
	}

	if sidx < 0 {
		return Result{-1, -1, 0}, nil
	}

	score := calculateScoreV1(T, P, sidx, eidx, bonus)

	var positions *[]int
	if withPos {
		pos := make([]int, M)
		pi := 0
		for j := sidx; j < eidx && pi < M; j++ {
			if T[j] == P[pi] {
				pos[pi] = j
				pi++
			}
		}
		positions = &pos
	}

	return Result{sidx, eidx, score}, positions
}

func calculateScoreV1(T, P []rune, sidx, eidx int, bonus []int32) int {
	M := len(P)
	score := 0
	pidx := 0
	inGap := false
	consecutive := 0
	prevBonus := int32(0)

	for j := sidx; j < eidx; j++ {
		if pidx < M && T[j] == P[pidx] {
			b := bonus[j]
			var matchScore int32
			if pidx == 0 {
				matchScore = int32(scoreMatch) + b*int32(bonusFirstCharMultiplier)
				prevBonus = b
			} else if consecutive > 0 {
				// Consecutive: use max(bonusConsecutive, prevBonus)
				consB := int32(bonusConsecutive)
				if prevBonus > consB {
					consB = prevBonus
				}
				matchScore = int32(scoreMatch) + consB
				prevBonus = consB
			} else {
				matchScore = int32(scoreMatch) + b
				prevBonus = b
			}
			score += int(matchScore)
			consecutive++
			inGap = false
			pidx++
		} else {
			if !inGap {
				score += scoreGapStart
				inGap = true
			} else {
				score += scoreGapExtension
			}
			consecutive = 0
			prevBonus = 0
		}
	}

	return score
}

// ExactMatchNaive finds an exact substring match
func ExactMatchNaive(caseSensitive, normalize, forward bool, text []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	M := len(pattern)
	if M == 0 {
		return Result{0, 0, 0}, &[]int{}
	}
	N := len(text)
	if N < M {
		return Result{-1, -1, 0}, nil
	}

	T := trimText(text, caseSensitive, normalize)
	P := trimText(pattern, caseSensitive, normalize)

	bonus := make([]int32, N)
	bonus[0] = bonusBoundaryWhite
	for i := 1; i < N; i++ {
		bonus[i] = bonusFor(charClassOf(text[i-1]), charClassOf(text[i]))
	}

	findMatch := func() (int, int) {
		if forward {
			for i := 0; i <= N-M; i++ {
				if matchAt(T, P, i) {
					return i, i + M
				}
			}
		} else {
			for i := N - M; i >= 0; i-- {
				if matchAt(T, P, i) {
					return i, i + M
				}
			}
		}
		return -1, -1
	}

	sidx, eidx := findMatch()
	if sidx < 0 {
		return Result{-1, -1, 0}, nil
	}

	score := int(bonus[sidx]) * bonusFirstCharMultiplier + scoreMatch
	for j := sidx + 1; j < eidx; j++ {
		consB := int32(bonusConsecutive)
		score += scoreMatch + int(consB)
	}

	var positions *[]int
	if withPos {
		pos := make([]int, M)
		for j := 0; j < M; j++ {
			pos[j] = sidx + j
		}
		positions = &pos
	}

	return Result{sidx, eidx, score}, positions
}

func matchAt(T, P []rune, pos int) bool {
	for j := 0; j < len(P); j++ {
		if T[pos+j] != P[j] {
			return false
		}
	}
	return true
}

// PrefixMatch checks for prefix match
func PrefixMatch(caseSensitive, normalize, forward bool, text []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	M := len(pattern)
	if M == 0 {
		return Result{0, 0, 0}, &[]int{}
	}
	N := len(text)
	if N < M {
		return Result{-1, -1, 0}, nil
	}

	T := trimText(text, caseSensitive, normalize)
	P := trimText(pattern, caseSensitive, normalize)

	if !matchAt(T, P, 0) {
		return Result{-1, -1, 0}, nil
	}

	return ExactMatchNaive(caseSensitive, normalize, true, text, pattern, withPos, slab)
}

// SuffixMatch checks for suffix match
func SuffixMatch(caseSensitive, normalize, forward bool, text []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	M := len(pattern)
	if M == 0 {
		return Result{0, 0, 0}, &[]int{}
	}
	N := len(text)
	if N < M {
		return Result{-1, -1, 0}, nil
	}

	T := trimText(text, caseSensitive, normalize)
	P := trimText(pattern, caseSensitive, normalize)

	if !matchAt(T, P, N-M) {
		return Result{-1, -1, 0}, nil
	}

	return ExactMatchNaive(caseSensitive, normalize, false, text, pattern, withPos, slab)
}

// EqualMatch checks for exact equality
func EqualMatch(caseSensitive, normalize, forward bool, text []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	if len(text) != len(pattern) {
		return Result{-1, -1, 0}, nil
	}
	return ExactMatchNaive(caseSensitive, normalize, true, text, pattern, withPos, slab)
}
