		for j := 0; j < N; j++ {
			if T[j] == P[pidx] {
				if pidx == 0 {
					sidx = j
				}
				pidx++
				if pidx == M {
					eidx = j + 1
					break
				}
			}
		}
	} else {
		pidx = M - 1
		for j := N - 1; j >= 0; j-- {
			if T[j] == P[pidx] {
				if pidx == M-1 {
					eidx = j + 1
				}
				pidx--
				if pidx < 0 {
					sidx = j
					break
				}
			}
		}
	}

	if sidx < 0 {
		return Result{-1, -1, 0}, nil
	}

	score := calculateScoreV1(T, P, sidx, eidx, bonus)

	var positions *[]int
	if withPos {
		pos := make([]int, M)
		pi := 0
		for j := sidx; j < eidx && pi < M; j++ {
			if T[j] == P[pi] {
				pos[pi] = j
				pi++
			}
		}
		positions = &pos
	}

	return Result{sidx, eidx, score}, positions
