}

// ExactMatchNaive finds an exact substring match
func ExactMatchNaive(caseSensitive, normalize, forward bool, text []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	M := len(pattern)
	if M == 0 {
		return Result{0, 0, 0}, &[]int{}
	}
	N := len(text)
	if N < M {
		return Result{-1, -1, 0}, nil
	}

	T := trimText(text, caseSensitive, normalize)
	P := trimText(pattern, caseSensitive, normalize)

	bonus := make([]int32, N)
	bonus[0] = bonusBoundaryWhite
	for i := 1; i < N; i++ {
		bonus[i] = bonusFor(charClassOf(text[i-1]), charClassOf(text[i]))
	}

	findMatch := func() (int, int) {
		if forward {
			for i := 0; i <= N-M; i++ {
				if matchAt(T, P, i) {
					return i, i + M
				}
			}
		} else {
			for i := N - M; i >= 0; i-- {
				if matchAt(T, P, i) {
					return i, i + M
				}
			}
		}
		return -1, -1
	}

	sidx, eidx := findMatch()
	if sidx < 0 {
		return Result{-1, -1, 0}, nil
	}

	score := int(bonus[sidx]) * bonusFirstCharMultiplier + scoreMatch
	for j := sidx + 1; j < eidx; j++ {
		consB := int32(bonusConsecutive)
		score += scoreMatch + int(consB)
	}

	var positions *[]int
	if withPos {
		pos := make([]int, M)
		for j := 0; j < M; j++ {
			pos[j] = sidx + j
		}
		positions = &pos
	}

	return Result{sidx, eidx, score}, positions
}

func matchAt(T, P []rune, pos int) bool {
	for j := 0; j < len(P); j++ {
		if T[pos+j] != P[j] {
			return false
		}
	}
	return true
}

// PrefixMatch checks for prefix match
func PrefixMatch(caseSensitive, normalize, forward bool, text []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	M := len(pattern)
	if M == 0 {
		return Result{0, 0, 0}, &[]int{}
	}
	N := len(text)
	if N < M {
		return Result{-1, -1, 0}, nil
	}

	T := trimText(text, caseSensitive, normalize)
	P := trimText(pattern, caseSensitive, normalize)

	if !matchAt(T, P, 0) {
		return Result{-1, -1, 0}, nil
	}

	return ExactMatchNaive(caseSensitive, normalize, true, text, pattern, withPos, slab)
}

// SuffixMatch checks for suffix match
func SuffixMatch(caseSensitive, normalize, forward bool, text []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	M := len(pattern)
	if M == 0 {
		return Result{0, 0, 0}, &[]int{}
	}
	N := len(text)
	if N < M {
		return Result{-1, -1, 0}, nil
	}

	T := trimText(text, caseSensitive, normalize)
	P := trimText(pattern, caseSensitive, normalize)

	if !matchAt(T, P, N-M) {
		return Result{-1, -1, 0}, nil
	}

	return ExactMatchNaive(caseSensitive, normalize, false, text, pattern, withPos, slab)
}

// EqualMatch checks for exact equality
func EqualMatch(caseSensitive, normalize, forward bool, text []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	if len(text) != len(pattern) {
		return Result{-1, -1, 0}, nil
	}
	return ExactMatchNaive(caseSensitive, normalize, true, text, pattern, withPos, slab)
}
