	N := len(text)
	if N < M {
		return Result{-1, -1, 0}, nil
	}

	T := trimText(text, caseSensitive, normalize)
	P := trimText(pattern, caseSensitive, normalize)

	bonus := make([]int32, N)
	bonus[0] = bonusBoundaryWhite
	for i := 1; i < N; i++ {
		bonus[i] = bonusFor(charClassOf(text[i-1]), charClassOf(text[i]))
	}

	findMatch := func() (int, int) {
		if forward {
			for i := 0; i <= N-M; i++ {
				if matchAt(T, P, i) {
					return i, i + M
				}
			}
		} else {
			for i := N - M; i >= 0; i-- {
				if matchAt(T, P, i) {
					return i, i + M
				}
			}
		}
		return -1, -1
	}

	sidx, eidx := findMatch()
	if sidx < 0 {
		return Result{-1, -1, 0}, nil
	}

	score := int(bonus[sidx]) * bonusFirstCharMultiplier + scoreMatch
	for j := sidx + 1; j < eidx; j++ {
		consB := int32(bonusConsecutive)
		score += scoreMatch + int(consB)
	}

