// ParsePattern parses a search query string into a Pattern
func ParsePattern(extended, fuzzy, caseSensitive, normalize, forward bool, algo AlgoType, delimiter Delimiter, nth []Range, withNth []Range, query string) *Pattern {
	runes := []rune(query)

