	Start int
	End   int
	Score int
}

type Slab struct {
	I16 []int16
	I32 []int32
}

func NewSlab() *Slab {
	return &Slab{
		I16: make([]int16, 100*100),
		I32: make([]int32, 100*100),
	}
}

func prepRunes(text []rune, caseSensitive, normalize bool) []rune {
	out := make([]rune, len(text))
	copy(out, text)
	for i, r := range out {
		if !caseSensitive {
			out[i] = unicode.ToLower(r)
		}
		if normalize {
			out[i] = normalizeRune(out[i])
		}
	}
	return out
