func calcBonus(text []rune, N int) []int32 {
	bonus := make([]int32, N)
	if N > 0 {
		bonus[0] = bonusBoundaryWhite // start of string
	}
	for i := 1; i < N; i++ {
		bonus[i] = bonusFor(charClassOf(text[i-1]), charClassOf(text[i]))
	}
	return bonus
}

// FuzzyMatchV2 implements optimal fuzzy matching
func FuzzyMatchV2(caseSensitive, normalize, forward bool, text []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	M := len(pattern)
	if M == 0 {
		return Result{0, 0, 0}, &[]int{}
	}
	N := len(text)
	if N == 0 || M > N {
		return Result{-1, -1, 0}, nil
	}

	T := prepRunes(text, caseSensitive, normalize)
	P := prepRunes(pattern, caseSensitive, normalize)
	bonus := calcBonus(text, N)

	// H[j] = best score of matching pattern[0..i] ending at text position j
	// C[j] = consecutive bonus (bonus propagated from previous consecutive match)
	type hCell struct {
		score int32
		cBonus int32 // consecutive/inherited bonus for propagation
	}

