		// We process left to right, maintaining running max
		for j := 0; j < N; j++ {
			if T[j] != P[i] {
				continue
			}
			b := bonus[j]
			best := hCell{score: -1 << 30}

			// Option 1: consecutive match (previous match at j-1)
			if j > 0 && H[j-1].score > 0 {
				prevCB := H[j-1].cBonus
				cb := prevCB
				if bonusConsecutive > cb {
					cb = bonusConsecutive
				}
				s := H[j-1].score + int32(scoreMatch) + cb
				if s > best.score {
					best = hCell{s, cb}
				}
			}

			// Option 2: gap match (match at some earlier position k < j-1)
			for k := 0; k < j-1; k++ {
				if H[k].score <= 0 {
					continue
				}
				gap := int32(j - k - 2) // number of gap extension chars
				gapPenalty := int32(scoreGapStart) + int32(scoreGapExtension)*gap
				s := H[k].score + gapPenalty + int32(scoreMatch) + b
				if s > best.score {
					best = hCell{s, b}
				}
			}

