package src

import "unicode"

type AlgoType int

const (
	AlgoV2 AlgoType = iota
	AlgoV1
)

type charClass int

const (
	charNonWord  charClass = iota
	charDelimiter          // space, tab
	charLower
	charUpper
	charLetter
	charNumber
)

const (
	scoreMatch               = 16
	scoreGapStart            = -3
	scoreGapExtension        = -1
	bonusBoundaryWhite       int32 = 9
	bonusBoundary            int32 = 5
	bonusCamel123            int32 = 4
	bonusConsecutive         int32 = 4
	bonusFirstCharMultiplier int32 = 2
)

func charClassOf(r rune) charClass {
	switch {
	case r == ' ' || r == '\t':
		return charDelimiter
	case r >= 'a' && r <= 'z':
		return charLower
	case r >= 'A' && r <= 'Z':
		return charUpper
	case r >= '0' && r <= '9':
		return charNumber
	case unicode.IsLower(r):
		return charLower
	case unicode.IsUpper(r):
		return charUpper
	case unicode.IsLetter(r):
		return charLetter
	case unicode.IsNumber(r):
		return charNumber
	default:
		return charNonWord
	}
}

func bonusFor(prevClass, class charClass) int32 {
	if class > charDelimiter {
		switch prevClass {
		case charDelimiter:
			return bonusBoundaryWhite
		case charNonWord:
			return bonusBoundary
		default:
			if prevClass == charLower && class == charUpper {
				return bonusCamel123
			}
		}
	}
	return 0
}

func normalizeRune(r rune) rune {
	if r < 0x00C0 {
		return r
	}
	norm := map[rune]rune{
		'À': 'A', 'Á': 'A', 'Â': 'A', 'Ã': 'A', 'Ä': 'A', 'Å': 'A',
		'Ç': 'C',
		'È': 'E', 'É': 'E', 'Ê': 'E', 'Ë': 'E',
		'Ì': 'I', 'Í': 'I', 'Î': 'I', 'Ï': 'I',
		'Ñ': 'N',
		'Ò': 'O', 'Ó': 'O', 'Ô': 'O', 'Õ': 'O', 'Ö': 'O', 'Ø': 'O',
		'Ù': 'U', 'Ú': 'U', 'Û': 'U', 'Ü': 'U',
		'Ý': 'Y', 'ß': 's',
		'à': 'a', 'á': 'a', 'â': 'a', 'ã': 'a', 'ä': 'a', 'å': 'a',
		'ç': 'c',
		'è': 'e', 'é': 'e', 'ê': 'e', 'ë': 'e',
		'ì': 'i', 'í': 'i', 'î': 'i', 'ï': 'i',
		'ñ': 'n',
		'ò': 'o', 'ó': 'o', 'ô': 'o', 'õ': 'o', 'ö': 'o', 'ø': 'o',
		'ù': 'u', 'ú': 'u', 'û': 'u', 'ü': 'u',
		'ý': 'y', 'ÿ': 'y',
	}
	if v, ok := norm[r]; ok {
		return v
	}
	return r
}

type Result struct {
	Start int
	End   int
	Score int
}

type Slab struct {
	I16 []int16
	I32 []int32
}

func NewSlab() *Slab {
	return &Slab{
		I16: make([]int16, 100*100),
		I32: make([]int32, 100*100),
	}
}

func prepRunes(text []rune, caseSensitive, normalize bool) []rune {
	out := make([]rune, len(text))
	copy(out, text)
	for i, r := range out {
		if !caseSensitive {
