		bestJ := -1
		for j := 0; j < N; j++ {
			if H[j].score > best.score {
				best = H[j]
				bestJ = j
			}
		}
		if bestJ < 0 {
			return Result{-1, -1, 0}, nil
		}
		var pos *[]int
		if withPos {
			p := []int{bestJ}
			pos = &p
		}
		return Result{bestJ, bestJ + 1, int(best.score)}, pos
