	if withPos {
		pos = &positions
	}
	return Result{start, end, int(bestScore)}, pos
}

// FuzzyMatchV1 implements greedy fuzzy matching
func FuzzyMatchV1(caseSensitive, normalize, forward bool, text []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	M := len(pattern)
	if M == 0 {
		return Result{0, 0, 0}, &[]int{}
	}
	N := len(text)
	if N == 0 || M > N {
		return Result{-1, -1, 0}, nil
	}

	T := prepRunes(text, caseSensitive, normalize)
	P := prepRunes(pattern, caseSensitive, normalize)
	bonus := calcBonus(text, N)

	sidx := -1
	eidx := -1
	pidx := 0

	if forward {
		for j := 0; j < N && pidx < M; j++ {
			if T[j] == P[pidx] {
				if pidx == 0 {
					sidx = j
				}
				pidx++
				eidx = j + 1
			}
		}
	} else {
		pidx = M - 1
		for j := N - 1; j >= 0 && pidx >= 0; j-- {
			if T[j] == P[pidx] {
				if pidx == M-1 {
					eidx = j + 1
				}
				pidx--
				if pidx < 0 {
					sidx = j
				}
			}
		}
	}

	if sidx < 0 || pidx > 0 {
		return Result{-1, -1, 0}, nil
	}

	score := scoreV1(T, P, sidx, eidx, bonus)

	var pos *[]int
	if withPos {
		p := make([]int, M)
		pi := 0
		for j := sidx; j < eidx && pi < M; j++ {
			if T[j] == P[pi] {
				p[pi] = j
				pi++
			}
		}
		pos = &p
	}

	return Result{sidx, eidx, score}, pos
}

func scoreV1(T, P []rune, sidx, eidx int, bonus []int32) int {
	M := len(P)
	score := 0
	pidx := 0
	inGap := false
	consecutive := 0
	prevBonus := int32(0)

	for j := sidx; j < eidx && pidx < M; j++ {
		if T[j] == P[pidx] {
			b := bonus[j]
			var add int32
			if pidx == 0 {
				add = int32(scoreMatch) + b*bonusFirstCharMultiplier
				prevBonus = b
			} else if consecutive > 0 {
				cb := bonusConsecutive
				if prevBonus > cb {
					cb = prevBonus
				}
				add = int32(scoreMatch) + cb
				prevBonus = cb
			} else {
				add = int32(scoreMatch) + b
				prevBonus = b
			}
			score += int(add)
			consecutive++
			inGap = false
			pidx++
		} else {
			if !inGap {
				score += scoreGapStart
				inGap = true
			} else {
				score += scoreGapExtension
			}
			consecutive = 0
			prevBonus = 0
		}
	}
	return score
}

// ExactMatchNaive finds exact substring matches
func ExactMatchNaive(caseSensitive, normalize, forward bool, text []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	M := len(pattern)
	if M == 0 {
		return Result{0, 0, 0}, &[]int{}
	}
	N := len(text)
	if N < M {
		return Result{-1, -1, 0}, nil
	}

	T := prepRunes(text, caseSensitive, normalize)
	P := prepRunes(pattern, caseSensitive, normalize)
	bonus := calcBonus(text, N)

	tryMatch := func(start, limit, step int) (int, int) {
		for i := start; i != limit; i += step {
			ok := true
			for j := 0; j < M; j++ {
				if T[i+j] != P[j] {
					ok = false
					break
				}
			}
			if ok {
				return i, i + M
			}
		}
		return -1, -1
	}

	var sidx, eidx int
	if forward {
		sidx, eidx = tryMatch(0, N-M+1, 1)
	} else {
		sidx, eidx = tryMatch(N-M, -1, -1)
	}
	if sidx < 0 {
		return Result{-1, -1, 0}, nil
	}

	score := int(int32(scoreMatch) + bonus[sidx]*bonusFirstCharMultiplier)
	for j := sidx + 1; j < eidx; j++ {
		score += scoreMatch + int(bonusConsecutive)
	}

	var pos *[]int
	if withPos {
		p := make([]int, M)
		for j := 0; j < M; j++ {
			p[j] = sidx + j
		}
		pos = &p
	}
	return Result{sidx, eidx, score}, pos
}

func PrefixMatch(caseSensitive, normalize, forward bool, text []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	if len(pattern) == 0 {
		return Result{0, 0, 0}, &[]int{}
	}
	if len(text) < len(pattern) {
		return Result{-1, -1, 0}, nil
	}
	T := prepRunes(text, caseSensitive, normalize)
	P := prepRunes(pattern, caseSensitive, normalize)
	for j := 0; j < len(P); j++ {
		if T[j] != P[j] {
			return Result{-1, -1, 0}, nil
		}
	}
	return ExactMatchNaive(caseSensitive, normalize, true, text, pattern, withPos, slab)
}

func SuffixMatch(caseSensitive, normalize, forward bool, text []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	if len(pattern) == 0 {
		return Result{0, 0, 0}, &[]int{}
	}
	N := len(text)
	M := len(pattern)
	if N < M {
		return Result{-1, -1, 0}, nil
	}
	T := prepRunes(text, caseSensitive, normalize)
	P := prepRunes(pattern, caseSensitive, normalize)
	offset := N - M
	for j := 0; j < M; j++ {
		if T[offset+j] != P[j] {
			return Result{-1, -1, 0}, nil
		}
	}
	return ExactMatchNaive(caseSensitive, normalize, false, text, pattern, withPos, slab)
}

func EqualMatch(caseSensitive, normalize, forward bool, text []rune, pattern []rune, withPos bool, slab *Slab) (Result, *[]int) {
	if len(text) != len(pattern) {
		return Result{-1, -1, 0}, nil
	}
	return ExactMatchNaive(caseSensitive, normalize, true, text, pattern, withPos, slab)
}
