// Delimiter for field splitting
type Delimiter struct {
	Str string
}

// IsDefault returns true if this is the default AWK-style delimiter
func (d Delimiter) IsDefault() bool {
	return d.Str == ""
}

// SplitFields splits a string into fields using the delimiter
func (d Delimiter) SplitFields(s string) []string {
	if d.IsDefault() {
		// AWK-style: split on whitespace
		return awkSplit(s)
	}
	return strings.Split(s, d.Str)
}

func awkSplit(s string) []string {
	var fields []string
	inField := false
	start := 0
	for i, r := range s {
		if unicode.IsSpace(r) {
			if inField {
				fields = append(fields, s[start:i])
				inField = false
			}
		} else {
			if !inField {
				start = i
				inField = true
			}
		}
	}
	if inField {
		fields = append(fields, s[start:])
	}
	return fields
}

// Range for field selection
type Range struct {
	Begin int // 0 means from start, negative means from end
	End   int // 0 means to end, negative means from end
}

// ParseRanges parses a comma-separated list of range expressions
func ParseRanges(s string) ([]Range, error) {
	if s == "" {
		return nil, nil
	}
	parts := strings.Split(s, ",")
	ranges := make([]Range, 0, len(parts))
	for _, part := range parts {
		r, ok := parseRange(part)
		if !ok {
			return nil, fmt.Errorf("invalid range: %s", part)
		}
		ranges = append(ranges, r)
	}
	return ranges, nil
}

func parseRange(s string) (Range, bool) {
	s = strings.TrimSpace(s)
	if s == "" {
		return Range{}, false
	}

	dotIdx := strings.Index(s, "..")
	if dotIdx >= 0 {
		beginStr := s[:dotIdx]
		endStr := s[dotIdx+2:]
		begin := 0
		end := 0
		var err error
		if beginStr != "" {
			begin, err = strconv.Atoi(beginStr)
			if err != nil {
				return Range{}, false
			}
		}
		if endStr != "" {
			end, err = strconv.Atoi(endStr)
			if err != nil {
				return Range{}, false
			}
		}
		return Range{Begin: begin, End: end}, true
	}

	n, err := strconv.Atoi(s)
	if err != nil {
		return Range{}, false
	}
	return Range{Begin: n, End: n}, true
}

// ExtractFields extracts fields from a string based on ranges and delimiter
func ExtractFields(s string, ranges []Range, delim Delimiter, stripLastDelimiter bool) string {
	if len(ranges) == 0 {
		return s
	}

	fields := delim.SplitFields(s)
	N := len(fields)

	var result strings.Builder
	first := true

	for _, r := range ranges {
		begin, end := r.Begin, r.End

		// Convert to 0-indexed
		var low, high int
		if begin == 0 {
			low = 0
		} else if begin > 0 {
			low = begin - 1
		} else {
			low = N + begin
		}
		if end == 0 {
			high = N - 1
		} else if end > 0 {
			high = end - 1
		} else {
			high = N + end
		}

		if low < 0 {
			low = 0
		}
		if high >= N {
			high = N - 1
		}

		for i := low; i <= high && i < N; i++ {
			if !first {
				result.WriteString(" ")
			}
			result.WriteString(fields[i])
			first = false
		}
	}

	return result.String()
}
