			continue
		}
		if r == '\'' || r == '"' {
			inQuote = r
			continue
		}
		if r == ' ' || r == '\t' || r == '\n' || r == '\r' {
			if current.Len() > 0 {
				args = append(args, current.String())
				current.Reset()
			}
			continue
		}
		current.WriteRune(r)
	}
	if current.Len() > 0 {
		args = append(args, current.String())
	}
	return args
}

func (o *Options) parse(args []string) error {
	for i := 0; i < len(args); i++ {
		arg := args[i]

		// Handle --flag=value syntax
		if strings.HasPrefix(arg, "--") {
			eqIdx := strings.Index(arg[2:], "=")
			var key, value string
			hasValue := false
			if eqIdx >= 0 {
				key = arg[2:2+eqIdx]
				value = arg[2+eqIdx+1:]
				hasValue = true
			} else {
				key = arg[2:]
			}

			getValue := func() (string, error) {
				if hasValue {
					return value, nil
				}
				i++
				if i >= len(args) {
					return "", fmt.Errorf("option --%s requires an argument", key)
				}
				return args[i], nil
			}

			switch key {
			case "help":
				o.Help = true
			case "version":
				o.Version = true
			case "man":
				o.Man = true
			case "bash":
				o.ShellBash = true
			case "zsh":
				o.ShellZsh = true
			case "fish":
				o.ShellFish = true
			case "extended", "x":
				o.Extended = true
			case "no-extended":
				o.Extended = false
			case "exact", "e":
				o.Exact = true
			case "no-exact":
				o.Exact = false
			case "ignore-case", "i":
				o.CaseSensitive = 0
			case "no-ignore-case":
				o.CaseSensitive = 1
			case "smart-case":
