			case "normalize":
				o.Normalize = true
			case "literal":
				o.Normalize = false
			case "no-normalize":
				o.Normalize = true
			case "no-sort", "no-s":
				o.Sort = false
			case "sort":
				o.Sort = true
			case "tac":
				o.Tac = true
			case "no-tac":
				o.Tac = false
			case "disabled":
				o.Disabled = true
			case "no-disabled":
				o.Disabled = false
			case "ansi":
