				} else {
					o.Tmux = "center,50%"
				}
			case "no-tmux":
				o.Tmux = ""
			default:
				// Try to handle unknown options gracefully
				// Check for --no- prefix
				if strings.HasPrefix(key, "no-") {
					// ignore unknown --no-xxx options
				} else if !hasValue {
					// might be a flag, just ignore
				}
				// Silently ignore unknown options for compatibility
			}
			continue
		}

		// Short options
		if strings.HasPrefix(arg, "-") && len(arg) > 1 && arg[1] != '-' {
			// Handle short options
			j := 1
			for j < len(arg) {
				ch := arg[j]
				switch ch {
				case 'h':
					o.Help = true
				case 'e':
					o.Exact = true
				case 'i':
					o.CaseSensitive = 0
				case 'm':
					if j+1 < len(arg) {
						rest := arg[j+1:]
						n, err := strconv.Atoi(rest)
						if err == nil {
							o.Multi = n
							j = len(arg)
							continue
						}
					}
					o.Multi = -1
				case '1':
					o.Select1 = true
				case '0':
					o.Exit0 = true
				case 'x':
					o.Extended = true
				case 's':
					o.Sort = true
				case 'f':
					// -f value
					if j+1 < len(arg) {
						o.Filter = arg[j+1:]
						j = len(arg)
					} else {
						i++
						if i < len(args) {
							o.Filter = args[i]
						}
					}
					continue
				case 'q':
					if j+1 < len(arg) {
						o.Query = arg[j+1:]
						j = len(arg)
					} else {
						i++
						if i < len(args) {
							o.Query = args[i]
						}
					}
					continue
				case 'n':
					var v string
					if j+1 < len(arg) {
						v = arg[j+1:]
						j = len(arg)
					} else {
						i++
						if i < len(args) {
							v = args[i]
						}
					}
					ranges, err := ParseRanges(v)
					if err == nil {
						o.Nth = ranges
					}
					continue
				case 'd':
					var v string
					if j+1 < len(arg) {
						v = arg[j+1:]
						j = len(arg)
					} else {
						i++
						if i < len(args) {
							v = args[i]
						}
					}
					o.Delimiter = Delimiter{Str: v}
					continue
				}
				j++
			}

			// Handle +s, +i, +x etc (toggle off)
		} else if strings.HasPrefix(arg, "+") && len(arg) > 1 {
			switch arg[1:] {
			case "s", "no-sort":
				o.Sort = false
			case "i", "no-ignore-case":
				o.CaseSensitive = 1
			case "x", "no-extended":
				o.Extended = false
			case "m":
				o.Multi = 0
			}
		} else if arg == "--" {
			// end of options
		}
	}

	// Apply scheme defaults
	switch o.Scheme {
	case "path":
		hasTiebreak := false
		for _, t := range args {
			if strings.HasPrefix(t, "--tiebreak") {
				hasTiebreak = true
				break
			}
		}
		if !hasTiebreak {
			o.Tiebreak = []string{"pathname", "length"}
		}
	case "history":
		hasTiebreak := false
		for _, t := range args {
			if strings.HasPrefix(t, "--tiebreak") {
				hasTiebreak = true
				break
			}
		}
		if !hasTiebreak {
			o.Tiebreak = []string{"index"}
		}
	}

	return nil
}

// Delimiter for field splitting
type Delimiter struct {
	Str string
}

// IsDefault returns true if this is the default AWK-style delimiter
func (d Delimiter) IsDefault() bool {
	return d.Str == ""
}

// SplitFields splits a string into fields using the delimiter
func (d Delimiter) SplitFields(s string) []string {
	if d.IsDefault() {
		// AWK-style: split on whitespace
		return awkSplit(s)
	}
	return strings.Split(s, d.Str)
}

func awkSplit(s string) []string {
	var fields []string
	inField := false
	start := 0
	for i, r := range s {
		if unicode.IsSpace(r) {
			if inField {
				fields = append(fields, s[start:i])
				inField = false
			}
		} else {
			if !inField {
				start = i
				inField = true
			}
		}
	}
	if inField {
		fields = append(fields, s[start:])
	}
	return fields
}

// Range for field selection
type Range struct {
	Begin int // 0 means from start, negative means from end
	End   int // 0 means to end, negative means from end
}

// ParseRanges parses a comma-separated list of range expressions
func ParseRanges(s string) ([]Range, error) {
	if s == "" {
		return nil, nil
	}
	parts := strings.Split(s, ",")
	ranges := make([]Range, 0, len(parts))
	for _, part := range parts {
		r, ok := parseRange(part)
		if !ok {
			return nil, fmt.Errorf("invalid range: %s", part)
		}
		ranges = append(ranges, r)
	}
	return ranges, nil
}

func parseRange(s string) (Range, bool) {
	s = strings.TrimSpace(s)
	if s == "" {
		return Range{}, false
	}

	dotIdx := strings.Index(s, "..")
	if dotIdx >= 0 {
		beginStr := s[:dotIdx]
		endStr := s[dotIdx+2:]
		begin := 0
		end := 0
		var err error
		if beginStr != "" {
			begin, err = strconv.Atoi(beginStr)
			if err != nil {
				return Range{}, false
			}
		}
		if endStr != "" {
			end, err = strconv.Atoi(endStr)
			if err != nil {
				return Range{}, false
			}
		}
		return Range{Begin: begin, End: end}, true
	}

	n, err := strconv.Atoi(s)
	if err != nil {
		return Range{}, false
	}
	return Range{Begin: n, End: n}, true
}

// ExtractFields extracts fields from a string based on ranges and delimiter
func ExtractFields(s string, ranges []Range, delim Delimiter, stripLastDelimiter bool) string {
	if len(ranges) == 0 {
		return s
	}

	fields := delim.SplitFields(s)
	N := len(fields)

	var result strings.Builder
	first := true

	for _, r := range ranges {
		begin, end := r.Begin, r.End

		// Convert to 0-indexed
		var low, high int
		if begin == 0 {
			low = 0
		} else if begin > 0 {
			low = begin - 1
		} else {
			low = N + begin
		}
		if end == 0 {
			high = N - 1
		} else if end > 0 {
			high = end - 1
		} else {
			high = N + end
		}

		if low < 0 {
			low = 0
		}
		if high >= N {
			high = N - 1
		}

		for i := low; i <= high && i < N; i++ {
			if !first {
				result.WriteString(" ")
			}
			result.WriteString(fields[i])
			first = false
		}
	}

	return result.String()
}
