// ParseOptions parses command-line arguments
func ParseOptions(args []string) (*Options, error) {
	opts := DefaultOptions()

	// Parse environment variable FZF_DEFAULT_OPTS_FILE first
	if optsFile := os.Getenv("FZF_DEFAULT_OPTS_FILE"); optsFile != "" {
		data, err := os.ReadFile(optsFile)
		if err == nil {
			fileArgs := parseArgsFromString(string(data))
			if err := opts.parse(fileArgs); err != nil {
				return nil, err
			}
		}
	}

	// Parse FZF_DEFAULT_OPTS
	if defaultOpts := os.Getenv("FZF_DEFAULT_OPTS"); defaultOpts != "" {
		envArgs := parseArgsFromString(defaultOpts)
		if err := opts.parse(envArgs); err != nil {
			return nil, err
		}
	}

	// Parse command line args
	if err := opts.parse(args); err != nil {
		return nil, err
	}

	return opts, nil
}

func parseArgsFromString(s string) []string {
	var args []string
	var current strings.Builder
	inQuote := rune(0)
	escaped := false

	for _, r := range s {
		if escaped {
			current.WriteRune(r)
			escaped = false
			continue
		}
		if r == '\\' {
			escaped = true
			continue
		}
		if inQuote != 0 {
			if r == inQuote {
				inQuote = 0
			} else {
				current.WriteRune(r)
			}
			continue
		}
		if r == '\'' || r == '"' {
			inQuote = r
			continue
		}
		if r == ' ' || r == '\t' || r == '\n' || r == '\r' {
			if current.Len() > 0 {
				args = append(args, current.String())
				current.Reset()
			}
			continue
		}
		current.WriteRune(r)
	}
	if current.Len() > 0 {
		args = append(args, current.String())
	}
	return args
