package src

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"os/exec"
	"sort"
	"strings"
	"unicode/utf8"
)

const (
	Version = "0.68.0"
	Commit  = "5676da4a"
)

// Item represents an input item
type Item struct {
	raw    string
	index  int
	runes  []rune
}

func newItem(raw string, index int) *Item {
	return &Item{
		raw:   raw,
		index: index,
		runes: []rune(raw),
	}
}

// RankedItem holds an item with its match score
type RankedItem struct {
	item      *Item
	score     int
	start     int
	end       int
	positions []int
}

// Run executes fzf with the given options
func Run(opts *Options) int {
	// Handle special modes first
	if opts.Version {
		fmt.Printf("%s (%s)\n", Version, Commit)
		return 0
	}

	if opts.Help {
		printHelp()
		return 0
	}

	if opts.Man {
		showMan()
		return 0
	}

	if opts.ShellBash {
		fmt.Print(GetBashScript())
		return 0
	}

	if opts.ShellZsh {
		fmt.Print(GetZshScript())
		return 0
	}

	if opts.ShellFish {
		fmt.Print(GetFishScript())
		return 0
	}

	// Filter mode
	if opts.Filter != "" {
		return runFilter(opts)
	}

	// Interactive mode
	return runInteractive(opts)
}

// showMan tries to show the man page
func showMan() {
	// Try to run man page
	manCmd := exec.Command("man", "fzf")
	manCmd.Stdin = os.Stdin
	manCmd.Stdout = os.Stdout
	manCmd.Stderr = os.Stderr
	if err := manCmd.Run(); err != nil {
		// Fall back to printing help
		fmt.Fprintln(os.Stderr, "man: fzf: No manual entry for fzf")
	}
}

// readItems reads input items from stdin
func readItems(opts *Options) []*Item {
	var items []*Item
	reader := bufio.NewReader(os.Stdin)
	index := 0

	if opts.ReadNul {
		// NUL-delimited input
		var buf strings.Builder
		for {
			ch, err := reader.ReadByte()
			if err != nil {
				if buf.Len() > 0 {
					items = append(items, newItem(buf.String(), index))
					index++
				}
				break
			}
			if ch == 0 {
				items = append(items, newItem(buf.String(), index))
				index++
				buf.Reset()
			} else {
				buf.WriteByte(ch)
			}
		}
	} else {
		// Line-delimited input
		for {
			line, err := reader.ReadString('\n')
			line = strings.TrimRight(line, "\n\r")
			if line != "" {
				items = append(items, newItem(line, index))
				index++
			}
			if err != nil {
				break
			}
		}
	}

	// Apply --tac (reverse)
	if opts.Tac {
		for i, j := 0, len(items)-1; i < j; i, j = i+1, j-1 {
			items[i], items[j] = items[j], items[i]
		}
	}

	// Apply --tail (keep only last N items)
	if opts.TailSize > 0 && len(items) > opts.TailSize {
		items = items[len(items)-opts.TailSize:]
	}

	// Add header lines
	headerItems := items[:opts.HeaderLines]
	if opts.HeaderLines > 0 && len(items) > opts.HeaderLines {
		items = items[opts.HeaderLines:]
		_ = headerItems
	}

	return items
}

// getDisplayText returns the text to display for an item (after --with-nth transformation)
func getDisplayText(item *Item, opts *Options) string {
	if len(opts.WithNth) == 0 && opts.WithNthStr == "" {
		return item.raw
	}
	if opts.WithNthStr != "" {
		return applyTemplate(item.raw, opts.WithNthStr, opts.Delimiter, item.index)
	}
	return ExtractFields(item.raw, opts.WithNth, opts.Delimiter, false)
}

// getSearchText returns the text to search against
func getSearchText(item *Item, opts *Options) string {
	if len(opts.Nth) == 0 {
		return getDisplayText(item, opts)
	}
	return ExtractFields(getDisplayText(item, opts), opts.Nth, opts.Delimiter, false)
}

// getOutputText returns the text to output for a matched item
func getOutputText(item *Item, opts *Options) string {
	if len(opts.AcceptNth) == 0 && opts.AcceptNthStr == "" {
		return item.raw
	}
	if opts.AcceptNthStr != "" {
		return applyTemplate(item.raw, opts.AcceptNthStr, opts.Delimiter, item.index)
	}
	return ExtractFields(item.raw, opts.AcceptNth, opts.Delimiter, true)
}

// applyTemplate applies a template with {n}, {1}, {2} etc. placeholders
func applyTemplate(line, template string, delim Delimiter, lineIndex int) string {
	fields := delim.SplitFields(line)
	result := template

	// Replace {n} with line index (0-based)
	result = strings.ReplaceAll(result, "{n}", fmt.Sprintf("%d", lineIndex))

	// Replace field references
	// Handle {1..}, {..3}, {1..3}, {1}
	var out strings.Builder
	i := 0
	tmplRunes := []rune(result)
	for i < len(tmplRunes) {
		if tmplRunes[i] == '{' {
			j := i + 1
			for j < len(tmplRunes) && tmplRunes[j] != '}' {
				j++
			}
			if j < len(tmplRunes) {
				spec := string(tmplRunes[i+1 : j])
				if fieldText, ok := resolveFieldSpec(spec, fields); ok {
					out.WriteString(fieldText)
					i = j + 1
					continue
				}
			}
		}
		out.WriteRune(tmplRunes[i])
		i++
	}
	return out.String()
}

func resolveFieldSpec(spec string, fields []string) (string, bool) {
	if spec == "n" {
		return "", false // handled above
	}
	ranges, err := ParseRanges(spec)
	if err != nil || len(ranges) == 0 {
		return "", false
	}
	N := len(fields)
	var parts []string
	for _, r := range ranges {
		begin, end := r.Begin, r.End
		var low, high int
		if begin == 0 {
			low = 0
		} else if begin > 0 {
			low = begin - 1
		} else {
			low = N + begin
		}
		if end == 0 {
			high = N - 1
		} else if end > 0 {
			high = end - 1
		} else {
			high = N + end
		}
		if low < 0 {
			low = 0
		}
		if high >= N {
			high = N - 1
		}
		for i := low; i <= high && i < N; i++ {
			parts = append(parts, fields[i])
		}
	}
	return strings.Join(parts, " "), true
}

// matchItem matches an item against a pattern
func matchItem(item *Item, pattern *Pattern, opts *Options, slab *Slab) (bool, int, int, int) {
	searchText := getSearchText(item, opts)
	searchRunes := []rune(searchText)

	result, matched := pattern.MatchRunes(searchRunes, slab)
	if !matched {
		return false, 0, 0, 0
	}
	return true, result.Score, result.Start, result.End
}

// Tiebreak compares two ranked items for sorting
func tiebreakCompare(a, b *RankedItem, tiebreaks []string) bool {
	if a.score != b.score {
		return a.score > b.score // higher score first
	}

	for _, tb := range tiebreaks {
		switch tb {
		case "length":
			la := utf8.RuneCountInString(a.item.raw)
			lb := utf8.RuneCountInString(b.item.raw)
			if la != lb {
				return la < lb // shorter first
			}
		case "chunk":
			// Compare length of matched whitespace-delimited chunk
			ca := matchedChunkLen(a)
			cb := matchedChunkLen(b)
			if ca != cb {
				return ca < cb
			}
		case "begin":
			if a.start != b.start {
				return a.start < b.start
			}
		case "end":
			// Compare end position (relative to end of string)
			ea := len([]rune(a.item.raw)) - a.end
			eb := len([]rune(b.item.raw)) - b.end
			if ea != eb {
				return ea < eb
			}
		case "pathname":
			// Prefer match in filename portion of path
			pa := pathnameScore(a)
			pb := pathnameScore(b)
			if pa != pb {
				return pa > pb
			}
		case "index":
			return a.item.index < b.item.index
		}
	}

	// Final fallback: by index
	return a.item.index < b.item.index
}

func matchedChunkLen(r *RankedItem) int {
	if r.start < 0 || r.end < 0 {
		return len(r.item.runes)
	}
	// Find the whitespace-delimited chunk containing the match
	runes := r.item.runes
	N := len(runes)

	// Find chunk start
	chunkStart := r.start
	for chunkStart > 0 && runes[chunkStart-1] != ' ' && runes[chunkStart-1] != '\t' {
		chunkStart--
	}
	// Find chunk end
	chunkEnd := r.end
	for chunkEnd < N && runes[chunkEnd] != ' ' && runes[chunkEnd] != '\t' {
		chunkEnd++
	}
	return chunkEnd - chunkStart
}

func pathnameScore(r *RankedItem) int {
	// Returns 1 if the match is in the filename portion, 0 otherwise
	if r.start < 0 {
		return 0
	}
	runes := r.item.runes
	for i := r.start; i < r.end && i < len(runes); i++ {
		if runes[i] == '/' || runes[i] == '\\' {
			return 0 // match starts before a path separator
		}
	}
	return 1
}

// runFilter runs fzf in filter mode (--filter)
func runFilter(opts *Options) int {
	query := opts.Filter

	var caseSensitive bool
	switch opts.CaseSensitive {
	case 1:
		caseSensitive = true
	case 0:
		caseSensitive = false
	default:
		// Smart case: case sensitive if any uppercase in query
		caseSensitive = false
		for _, r := range query {
			if r >= 'A' && r <= 'Z' {
				caseSensitive = true
				break
			}
		}
	}

	isExact := opts.Exact
	algo := opts.Algo

	if opts.Scheme == "history" {
		algo = AlgoV2
	}

	pattern := buildPattern(query, opts.Extended, isExact, caseSensitive, opts.Normalize, opts.Algo)

	// Read all items
	items := readItems(opts)

	var matched []*RankedItem
	slab := NewSlab()

	for _, item := range items {
		searchText := getSearchText(item, opts)
		searchRunes := []rune(searchText)

		result, ok := matchRunes(pattern, searchRunes, caseSensitive, opts.Normalize, algo, slab)
		if ok {
			ri := &RankedItem{
				item:  item,
				score: result.Score,
				start: result.Start,
				end:   result.End,
			}
			matched = append(matched, ri)
		}
	}

	// Sort if needed
	if opts.Sort {
		sort.SliceStable(matched, func(i, j int) bool {
			return tiebreakCompare(matched[i], matched[j], opts.Tiebreak)
		})
	}

	// Output
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	if opts.PrintQuery {
		if opts.PrintNul {
			fmt.Fprintf(writer, "%s\x00", query)
		} else {
			fmt.Fprintf(writer, "%s\n", query)
		}
	}

	if len(matched) == 0 {
		return 1
	}

	for _, ri := range matched {
		outputText := getOutputText(ri.item, opts)
		if opts.PrintNul {
			fmt.Fprintf(writer, "%s\x00", outputText)
		} else {
			fmt.Fprintf(writer, "%s\n", outputText)
		}
	}

	return 0
}

// PatternState holds the parsed pattern state
type PatternState struct {
	empty bool
	terms [][]matchTerm
}

type termType int

const (
	termFuzzy  termType = iota
	termExact
	termPrefix
	termSuffix
	termEqual
)

type matchTerm struct {
	typ    termType
	inv    bool
	text   []rune
	caseSensitive bool
}

func buildPattern(query string, extended, exact, caseSensitive, normalize bool, algo AlgoType) *PatternState {
	if query == "" {
		return &PatternState{empty: true}
	}

	runes := []rune(query)

	if !extended {
		typ := termFuzzy
		if exact {
			typ = termExact
		}
		term := matchTerm{typ: typ, text: runes, caseSensitive: caseSensitive}
		return &PatternState{terms: [][]matchTerm{{term}}}
	}

	// Parse extended syntax
	terms := parseExtended(runes, exact, caseSensitive)
	return &PatternState{terms: terms}
}

func parseExtended(runes []rune, exact, caseSensitive bool) [][]matchTerm {
	var orGroups [][]matchTerm
	var andGroup []matchTerm

	i := 0
	for i < len(runes) {
		// Skip spaces
		for i < len(runes) && runes[i] == ' ' {
			i++
		}
		if i >= len(runes) {
			break
		}

		// Check for OR operator: " | " or just "|"
		if runes[i] == '|' {
			orGroups = append(orGroups, andGroup)
			andGroup = nil
			i++
			for i < len(runes) && runes[i] == ' ' {
				i++
			}
			continue
		}

		// Parse term
		term, end := parseTerm(runes, i, exact, caseSensitive)
		if term != nil {
			andGroup = append(andGroup, *term)
		}
		if end <= i {
			i++
		} else {
			i = end
		}
	}

	if len(andGroup) > 0 || len(orGroups) > 0 {
		orGroups = append(orGroups, andGroup)
	}

	return orGroups
}

func parseTerm(runes []rune, start int, exact, caseSensitive bool) (*matchTerm, int) {
	i := start
	inv := false

	if i < len(runes) && runes[i] == '!' {
		inv = true
		i++
		// Also handle !^, !'
		if i < len(runes) && runes[i] == '!' {
			// double ! - not a special case, treat as literal
			i = start
			inv = false
		}
	}

	if i >= len(runes) {
		return nil, i
	}

	typ := termFuzzy
	if exact {
		typ = termExact
	}

	hasPrefix := false
	hasSuffix := false

	switch runes[i] {
	case '\'':
		typ = termExact
		if exact {
			typ = termFuzzy
		}
		i++
	case '^':
		hasPrefix = true
		i++
	case '=':
		typ = termEqual
		i++
	}

	// Collect text until whitespace or end
	j := i
	for j < len(runes) && runes[j] != ' ' {
		j++
	}

	text := runes[i:j]

	// Check for suffix $
	if len(text) > 0 && text[len(text)-1] == '$' {
		text = text[:len(text)-1]
		hasSuffix = true
	}

	if len(text) == 0 {
		return nil, j
	}

	if hasPrefix {
		typ = termPrefix
	} else if hasSuffix {
		typ = termSuffix
	}

	// Determine case sensitivity for this term
	cs := caseSensitive
	if !cs {
		for _, r := range text {
			if r >= 'A' && r <= 'Z' {
				cs = true
				break
			}
		}
	}

	term := &matchTerm{
		typ:           typ,
		inv:           inv,
		text:          text,
		caseSensitive: cs,
	}
	return term, j
}

type matchResult struct {
	Score int
	Start int
	End   int
}

func matchRunes(pattern *PatternState, runes []rune, caseSensitive, normalize bool, algo AlgoType, slab *Slab) (matchResult, bool) {
	if pattern.empty {
		return matchResult{Score: 0}, true
	}

	var bestResult matchResult
	matched := false

	for _, group := range pattern.terms {
		groupMatch := true
		groupScore := 0
		groupStart := len(runes)
		groupEnd := 0

		for _, term := range group {
			if len(term.text) == 0 {
				continue
			}

			res := runTerm(runes, term, algo, normalize, slab)

			if term.inv {
				if res.Start >= 0 {
					groupMatch = false
					break
				}
			} else {
				if res.Start < 0 {
					groupMatch = false
					break
				}
				groupScore += res.Score
				if res.Start < groupStart {
					groupStart = res.Start
				}
				if res.End > groupEnd {
					groupEnd = res.End
				}
			}
		}

		if groupMatch {
			if !matched || groupScore > bestResult.Score {
				bestResult = matchResult{
					Score: groupScore,
					Start: groupStart,
					End:   groupEnd,
				}
				if groupStart == len(runes) {
					bestResult.Start = 0
				}
				matched = true
			}
		}
	}

	return bestResult, matched
}

func runTerm(runes []rune, term matchTerm, algo AlgoType, normalize bool, slab *Slab) Result {
	cs := term.caseSensitive

	switch term.typ {
	case termFuzzy:
		if algo == AlgoV2 {
			r, _ := FuzzyMatchV2(cs, normalize, true, runes, term.text, false, slab)
			return r
		}
		r, _ := FuzzyMatchV1(cs, normalize, true, runes, term.text, false, slab)
		return r
	case termExact:
		r, _ := ExactMatchNaive(cs, normalize, true, runes, term.text, false, slab)
		return r
	case termPrefix:
		r, _ := PrefixMatch(cs, normalize, true, runes, term.text, false, slab)
		return r
	case termSuffix:
		r, _ := SuffixMatch(cs, normalize, false, runes, term.text, false, slab)
		return r
	case termEqual:
		r, _ := EqualMatch(cs, normalize, true, runes, term.text, false, slab)
		return r
	}
	return Result{-1, -1, 0}
}

