// fzfMain is the main entry point
func fzfMain() int {
	args := os.Args[1:]

	opts, err := ParseOptions(args)
	if err != nil {
		fmt.Fprintf(os.Stderr, "fzf: %v\n", err)
		return 2
	}

	return Run(opts)
}

// Placeholder for ANSI stripping
func stripAnsi(s string) string {
	// Simple ANSI escape code stripper
	var result strings.Builder
	i := 0
	runes := []rune(s)
	for i < len(runes) {
		if runes[i] == '\x1b' && i+1 < len(runes) && runes[i+1] == '[' {
			// Skip escape sequence
			i += 2
			for i < len(runes) && runes[i] != 'm' && runes[i] != 'K' && runes[i] != 'J' {
				i++
			}
			if i < len(runes) {
				i++ // skip terminator
			}
		} else {
			result.WriteRune(runes[i])
			i++
		}
	}
	return result.String()
}

// readFromStdin or FZF_DEFAULT_COMMAND
func getInputReader(opts *Options) io.Reader {
	// Check if stdin is a terminal (not piped)
	if isTerminal(os.Stdin) {
		// Check FZF_DEFAULT_COMMAND
		if cmd := os.Getenv("FZF_DEFAULT_COMMAND"); cmd != "" {
			return execCommand(cmd)
		}
		// Walk files
		return walkFiles(opts)
	}
	return os.Stdin
}

func isTerminal(f *os.File) bool {
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	return fi.Mode()&os.ModeCharDevice != 0
}

func execCommand(cmd string) io.Reader {
	shell := "/bin/sh"
	c := exec.Command(shell, "-c", cmd)
	out, err := c.Output()
	if err != nil {
		return strings.NewReader("")
	}
	return strings.NewReader(string(out))
}

func walkFiles(opts *Options) io.Reader {
	// Simple file walker
	pr, pw := io.Pipe()
	go func() {
		defer pw.Close()
		for _, root := range opts.WalkerRoot {
			walkDir(pw, root, opts)
		}
	}()
	return pr
}

func walkDir(w io.Writer, dir string, opts *Options) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}

	walkerParts := strings.Split(opts.Walker, ",")
	wantFiles := false
	wantDirs := false
	wantFollow := false
	wantHidden := false
	for _, p := range walkerParts {
		switch strings.TrimSpace(p) {
		case "file":
			wantFiles = true
		case "dir":
			wantDirs = true
		case "follow":
			wantFollow = true
		case "hidden":
			wantHidden = true
		}
	}

	skipDirs := make(map[string]bool)
	for _, s := range opts.WalkerSkip {
		skipDirs[strings.TrimSpace(s)] = true
	}

	for _, e := range entries {
		name := e.Name()

		// Check hidden
		if !wantHidden && strings.HasPrefix(name, ".") {
			continue
		}

		path := dir + "/" + name
		if dir == "." {
			path = name
		}

		if e.IsDir() {
			if skipDirs[name] {
				continue
			}
			if wantDirs {
				fmt.Fprintln(w, path)
			}
			walkDir(w, path, opts)
		} else if e.Type()&os.ModeSymlink != 0 {
			if wantFollow {
				fi, err := os.Stat(path)
				if err == nil && fi.IsDir() {
					if skipDirs[name] {
						continue
					}
					if wantDirs {
						fmt.Fprintln(w, path)
					}
					walkDir(w, path, opts)
				} else if wantFiles {
					fmt.Fprintln(w, path)
				}
			} else if wantFiles {
				fmt.Fprintln(w, path)
			}
		} else if wantFiles {
			fmt.Fprintln(w, path)
		}
	}
}
