}

// winsize holds terminal window size
type winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func getTermSize(fd uintptr) (int, int) {
	ws := &winsize{}
	syscall.Syscall(syscall.SYS_IOCTL, fd, syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(ws)))
	return int(ws.Col), int(ws.Row)
}

// Raw terminal mode
type termios struct {
	Iflag  uint32
	Oflag  uint32
	Cflag  uint32
	Lflag  uint32
	Cc     [20]uint8
	Ispeed uint32
	Ospeed uint32
}

func tcGetAttr(fd uintptr) (*termios, error) {
	t := &termios{}
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, syscall.TCGETS, uintptr(unsafe.Pointer(t)))
	if errno != 0 {
		return nil, errno
	}
	return t, nil
}

func tcSetAttr(fd uintptr, t *termios) error {
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, syscall.TCSETS, uintptr(unsafe.Pointer(t)))
	if errno != 0 {
		return errno
	}
	return nil
}

func cfmakeraw(t *termios) {
	t.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	t.Oflag &^= syscall.OPOST
	t.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	t.Cflag &^= syscall.CSIZE | syscall.PARENB
	t.Cflag |= syscall.CS8
	t.Cc[syscall.VMIN] = 1
	t.Cc[syscall.VTIME] = 0
}

func newTerminal(opts *Options, items []*Item) *Terminal {
	t := &Terminal{
		opts:          opts,
		input:         items,
		query:         []rune(opts.Query),
		cursor:        len([]rune(opts.Query)),
		multiSelected: make(map[int]bool),
		slab:          NewSlab(),
		expectKeys:    make(map[string]bool),
	}

	// Parse expect keys
	if opts.Expect != "" {
		for _, k := range strings.Split(opts.Expect, ",") {
			t.expectKeys[strings.TrimSpace(k)] = true
		}
	}

	return t
}

func (t *Terminal) Run() ([]string, string, int) {
	// Try to open /dev/tty
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		// Fall back to stderr for output
		tty = os.Stderr
	}
	t.tty = tty

	// Get terminal size
	t.width, t.height = getTermSize(tty.Fd())
	if t.width <= 0 {
		t.width = 80
	}
	if t.height <= 0 {
		t.height = 24
	}

	// Set raw mode
	oldState, err := tcGetAttr(tty.Fd())
	if err == nil {
		newState := *oldState
		cfmakeraw(&newState)
		tcSetAttr(tty.Fd(), &newState)
		defer tcSetAttr(tty.Fd(), oldState)
	}

	// Handle signals
	sigch := make(chan os.Signal, 1)
	signal.Notify(sigch, syscall.SIGWINCH, syscall.SIGTERM, syscall.SIGINT)
	defer signal.Stop(sigch)

	// Initial filter
	t.updateFilter()

	// Render initial screen
	t.render()

	// Input loop
	reader := bufio.NewReader(tty)
	var selectedKey string

	for {
		select {
		case sig := <-sigch:
			switch sig {
			case syscall.SIGWINCH:
				t.width, t.height = getTermSize(tty.Fd())
				t.render()
			case syscall.SIGTERM, syscall.SIGINT:
				t.clearScreen()
				return nil, "", 130
			}
		default:
		}

		b, err := reader.ReadByte()
		if err != nil {
			break
		}

		switch int(b) {
		case keyCtrlC, keyCtrlG:
			t.clearScreen()
			return nil, "", 130
		case keyEscape:
			// Check for escape sequences
			next, err := reader.ReadByte()
			if err != nil || next != '[' {
				// Pure escape = exit
				t.clearScreen()
				return nil, "", 130
			}
			seq, _ := reader.ReadByte()
			t.handleEscSeq(seq)
			t.render()
			continue
		case keyEnter:
			t.clearScreen()
			results := t.getSelected()
			if len(results) == 0 && len(t.filtered) > 0 {
				out := getOutputText(t.filtered[t.selected].item, t.opts)
				return []string{out}, selectedKey, 0
			}
			return results, selectedKey, 0
		case keyTab:
			if t.opts.Multi != 0 {
				t.toggleSelect()
				t.moveDown()
			}
			t.render()
			continue
		case 9+64: // Shift-Tab (typically ^[[Z)
			if t.opts.Multi != 0 {
				t.toggleSelect()
				t.moveUp()
			}
			t.render()
			continue
		case keyCtrlJ, keyCtrlN:
			t.moveDown()
		case keyCtrlK, keyCtrlP:
			t.moveUp()
		case keyCtrlA:
			t.cursor = 0
		case keyCtrlE:
			t.cursor = len(t.query)
		case keyCtrlB:
			if t.cursor > 0 {
				t.cursor--
			}
		case keyCtrlF:
			if t.cursor < len(t.query) {
				t.cursor++
			}
		case keyCtrlH, keyBackspace:
			if t.cursor > 0 {
				t.query = append(t.query[:t.cursor-1], t.query[t.cursor:]...)
				t.cursor--
				t.updateFilter()
			}
		case keyCtrlD:
			if t.cursor < len(t.query) {
				t.query = append(t.query[:t.cursor], t.query[t.cursor+1:]...)
				t.updateFilter()
			}
		case keyCtrlU:
			t.query = t.query[t.cursor:]
			t.cursor = 0
			t.updateFilter()
		case keyCtrlW:
			// Delete word backward
			if t.cursor > 0 {
				end := t.cursor
				for end > 0 && t.query[end-1] == ' ' {
					end--
				}
				for end > 0 && t.query[end-1] != ' ' {
					end--
				}
				t.query = append(t.query[:end], t.query[t.cursor:]...)
				t.cursor = end
				t.updateFilter()
			}
		default:
			if b >= 32 || b == keyTab {
				// Printable character or tab - add to query
				// Handle multi-byte UTF-8
				runes := []rune{rune(b)}
				if b >= 0x80 {
					// Multi-byte UTF-8
					nBytes := 0
					if b&0xE0 == 0xC0 {
						nBytes = 1
					} else if b&0xF0 == 0xE0 {
						nBytes = 2
					} else if b&0xF8 == 0xF0 {
						nBytes = 3
					}
					buf := []byte{b}
					for k := 0; k < nBytes; k++ {
						next, err := reader.ReadByte()
						if err != nil {
							break
						}
						buf = append(buf, next)
					}
					runes = []rune(string(buf))
				}
				for _, r := range runes {
					t.query = append(t.query[:t.cursor], append([]rune{r}, t.query[t.cursor:]...)...)
					t.cursor++
				}
				t.updateFilter()
			}
		}

		t.render()
	}

	t.clearScreen()
	return nil, "", 1
}

func (t *Terminal) handleEscSeq(seq byte) {
	switch seq {
	case 'A': // Up arrow
		t.moveUp()
	case 'B': // Down arrow
		t.moveDown()
	case 'C': // Right arrow
		if t.cursor < len(t.query) {
			t.cursor++
		}
	case 'D': // Left arrow
		if t.cursor > 0 {
			t.cursor--
		}
	}
}

func (t *Terminal) moveUp() {
	if t.opts.Layout == "reverse" || t.opts.Layout == "reverse-list" {
		t.moveNext()
	} else {
		t.movePrev()
	}
}

func (t *Terminal) moveDown() {
	if t.opts.Layout == "reverse" || t.opts.Layout == "reverse-list" {
		t.movePrev()
	} else {
		t.moveNext()
	}
}

func (t *Terminal) moveNext() {
	if len(t.filtered) == 0 {
		return
	}
	if t.selected < len(t.filtered)-1 {
		t.selected++
	} else if t.opts.Cycle {
		t.selected = 0
		t.offset = 0
	}
}

func (t *Terminal) movePrev() {
	if len(t.filtered) == 0 {
		return
	}
	if t.selected > 0 {
		t.selected--
	} else if t.opts.Cycle {
		t.selected = len(t.filtered) - 1
	}
}

func (t *Terminal) toggleSelect() {
	if len(t.filtered) == 0 {
		return
	}
	idx := t.filtered[t.selected].item.index
	if t.multiSelected[idx] {
		delete(t.multiSelected, idx)
	} else {
		if t.opts.Multi < 0 || len(t.multiSelected) < t.opts.Multi {
			t.multiSelected[idx] = true
		}
	}
}

func (t *Terminal) getSelected() []string {
	if len(t.multiSelected) > 0 {
		var results []string
		// Output in original order
		for _, item := range t.input {
			if t.multiSelected[item.index] {
				results = append(results, getOutputText(item, t.opts))
			}
		}
		return results
	}
	return nil
}

func (t *Terminal) updateFilter() {
	t.selected = 0
	t.offset = 0

	queryStr := string(t.query)

	var caseSensitive bool
	switch t.opts.CaseSensitive {
	case 1:
		caseSensitive = true
	case 0:
		caseSensitive = false
	default:
		caseSensitive = false
		for _, r := range t.query {
			if r >= 'A' && r <= 'Z' {
				caseSensitive = true
				break
			}
		}
	}

	t.pattern = buildPattern(queryStr, t.opts.Extended, t.opts.Exact, caseSensitive, t.opts.Normalize, t.opts.Algo)

	var filtered []*RankedItem

	for _, item := range t.input {
		searchText := getSearchText(item, t.opts)
		searchRunes := []rune(searchText)

		if t.pattern.empty || t.opts.Disabled || t.opts.Raw {
			filtered = append(filtered, &RankedItem{item: item, score: 0})
			continue
		}

		result, ok := matchRunes(t.pattern, searchRunes, caseSensitive, t.opts.Normalize, t.opts.Algo, t.slab)
		if ok {
			filtered = append(filtered, &RankedItem{
				item:  item,
				score: result.Score,
				start: result.Start,
				end:   result.End,
			})
		}
	}

	if t.opts.Sort && !t.pattern.empty {
		sort.SliceStable(filtered, func(i, j int) bool {
			return tiebreakCompare(filtered[i], filtered[j], t.opts.Tiebreak)
		})
	}

	t.filtered = filtered
}

func (t *Terminal) render() {
	tty := t.tty

	// Clear screen by moving cursor to home
	fmt.Fprint(tty, "\x1b[?25l") // hide cursor

	listHeight := t.height - 1 // reserve 1 line for prompt
	if listHeight < 1 {
		listHeight = 1
	}

	// Ensure selected is visible
	if t.selected >= t.offset+listHeight {
		t.offset = t.selected - listHeight + 1
	}
	if t.selected < t.offset {
		t.offset = t.selected
	}

	// Clear screen
	fmt.Fprint(tty, "\x1b[2J\x1b[H")

	reverse := t.opts.Layout == "reverse" || t.opts.Layout == "reverse-list"

	if reverse {
		// Render prompt first, then list below
		t.renderPrompt()
		fmt.Fprintln(tty)
		for i := t.offset; i < t.offset+listHeight && i < len(t.filtered); i++ {
			t.renderItem(i)
			if i < t.offset+listHeight-1 {
				fmt.Fprintln(tty)
			}
		}
	} else {
		// Default: list above, prompt below
		startRow := t.height - listHeight - 1
		if startRow < 0 {
			startRow = 0
		}

		// Print empty lines above
		for i := 0; i < startRow; i++ {
			fmt.Fprintln(tty)
		}

		for i := t.offset; i < t.offset+listHeight && i < len(t.filtered); i++ {
			t.renderItem(i)
			if i < t.offset+listHeight-1 {
				fmt.Fprintln(tty)
			}
		}

		// Fill remaining list area
		displayed := len(t.filtered) - t.offset
		if displayed > listHeight {
			displayed = listHeight
		}
		for i := displayed; i < listHeight; i++ {
			fmt.Fprintln(tty)
		}

		t.renderPrompt()
	}

	fmt.Fprint(tty, "\x1b[?25h") // show cursor
}

func (t *Terminal) renderItem(idx int) {
	item := t.filtered[idx].item
	text := getDisplayText(item, t.opts)

	isSelected := idx == t.selected
	isMulti := t.multiSelected[item.index]

	if t.opts.NoUnicode {
		if isMulti {
			fmt.Fprint(t.tty, ">")
		} else if isSelected {
			fmt.Fprint(t.tty, ">")
		} else {
			fmt.Fprint(t.tty, " ")
		}
	} else {
		if isMulti {
			fmt.Fprint(t.tty, "┃")
		} else if isSelected {
			fmt.Fprint(t.tty, "▌")
		} else {
			fmt.Fprint(t.tty, " ")
		}
	}

	if isSelected && !t.opts.NoBold {
		fmt.Fprint(t.tty, "\x1b[1m")
	}

	// Truncate to width
	runes := []rune(text)
	maxWidth := t.width - 2
	if maxWidth < 0 {
		maxWidth = 0
	}
	if len(runes) > maxWidth {
		runes = runes[:maxWidth]
	}
	fmt.Fprint(t.tty, string(runes))

	if isSelected && !t.opts.NoBold {
		fmt.Fprint(t.tty, "\x1b[0m")
	}
}

func (t *Terminal) renderPrompt() {
	info := ""
	if len(t.filtered) > 0 {
		info = fmt.Sprintf("%d/%d", len(t.filtered), len(t.input))
	} else {
		info = fmt.Sprintf("0/%d", len(t.input))
	}

	prompt := "> "
	if t.opts.Prompt != "" {
		prompt = t.opts.Prompt
	}

	queryStr := string(t.query)

	// Print info line
	fmt.Fprintf(t.tty, "  %s", info)
	fmt.Fprintln(t.tty)

	// Print prompt
	fmt.Fprintf(t.tty, "%s%s", prompt, queryStr)

	// Position cursor
	cursorPos := len([]rune(prompt)) + t.cursor + 1
	fmt.Fprintf(t.tty, "\x1b[%dG", cursorPos)
}

func (t *Terminal) clearScreen() {
	fmt.Fprint(t.tty, "\x1b[2J\x1b[H")
	fmt.Fprint(t.tty, "\x1b[?25h") // show cursor
}

// runInteractive runs fzf in interactive/TUI mode
func runInteractive(opts *Options) int {
	// Read input
	var items []*Item

	stdinReader := getInputReader(opts)
	reader := bufio.NewReader(stdinReader)
	index := 0

	if opts.ReadNul {
		var buf strings.Builder
		for {
			ch, err := reader.ReadByte()
			if err != nil {
				if buf.Len() > 0 {
					items = append(items, newItem(buf.String(), index))
					index++
				}
				break
			}
			if ch == 0 {
				items = append(items, newItem(buf.String(), index))
				index++
				buf.Reset()
			} else {
				buf.WriteByte(ch)
			}
		}
	} else {
		for {
			line, err := reader.ReadString('\n')
			line = strings.TrimRight(line, "\n\r")
			if line != "" {
				items = append(items, newItem(line, index))
				index++
			}
			if err != nil {
				break
			}
		}
	}

	// Apply --tac
	if opts.Tac {
		for i, j := 0, len(items)-1; i < j; i, j = i+1, j-1 {
			items[i], items[j] = items[j], items[i]
		}
	}

	// Apply --tail
	if opts.TailSize > 0 && len(items) > opts.TailSize {
		items = items[len(items)-opts.TailSize:]
	}

	// Extract header lines
	var headerItems []string
	if opts.HeaderLines > 0 && len(items) >= opts.HeaderLines {
		for i := 0; i < opts.HeaderLines; i++ {
			headerItems = append(headerItems, items[i].raw)
		}
		items = items[opts.HeaderLines:]
	}
	_ = headerItems

	// --select-1 and --exit-0 modes
	if opts.Select1 || opts.Exit0 {
		var filtered []*RankedItem
		slab := NewSlab()

		queryStr := opts.Query
		caseSensitive := opts.CaseSensitive == 1
		if opts.CaseSensitive == -1 {
			for _, r := range queryStr {
				if r >= 'A' && r <= 'Z' {
					caseSensitive = true
					break
				}
			}
		}
		pattern := buildPattern(queryStr, opts.Extended, opts.Exact, caseSensitive, opts.Normalize, opts.Algo)

		for _, item := range items {
			searchText := getSearchText(item, opts)
			searchRunes := []rune(searchText)

			if pattern.empty {
				filtered = append(filtered, &RankedItem{item: item})
				continue
			}

			result, ok := matchRunes(pattern, searchRunes, caseSensitive, opts.Normalize, opts.Algo, slab)
			if ok {
				filtered = append(filtered, &RankedItem{item: item, score: result.Score})
			}
		}

		if opts.Exit0 && len(filtered) == 0 {
			return 1
		}

		if opts.Select1 && len(filtered) == 1 {
			outputText := getOutputText(filtered[0].item, opts)
			writer := bufio.NewWriter(os.Stdout)
			if opts.PrintQuery {
				if opts.PrintNul {
					fmt.Fprintf(writer, "%s\x00", queryStr)
				} else {
					fmt.Fprintln(writer, queryStr)
				}
			}
			if opts.PrintNul {
				fmt.Fprintf(writer, "%s\x00", outputText)
			} else {
				fmt.Fprintln(writer, outputText)
			}
			writer.Flush()
			return 0
		}
	}

	// Check if we have a terminal to display the TUI
	// Check if stdin AND stdout are TTY
	if !isTerminal(os.Stdin) || !isTerminal(os.Stdout) {
		// We may be in a pipeline, but still need to show TUI on /dev/tty
	}

	// Run TUI
	term := newTerminal(opts, items)
	results, key, exitCode := term.Run()

	if exitCode != 0 {
		return exitCode
	}

	if len(results) == 0 {
		return 1
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	if opts.PrintQuery {
		if opts.PrintNul {
			fmt.Fprintf(writer, "%s\x00", opts.Query)
		} else {
			fmt.Fprintln(writer, opts.Query)
		}
	}

	if key != "" {
		if opts.PrintNul {
			fmt.Fprintf(writer, "%s\x00", key)
		} else {
			fmt.Fprintln(writer, key)
		}
	} else if len(term.expectKeys) > 0 {
		// Print empty key
		if opts.PrintNul {
			fmt.Fprintf(writer, "\x00")
		} else {
			fmt.Fprintln(writer)
		}
	}

	for _, r := range results {
		if opts.PrintNul {
			fmt.Fprintf(writer, "%s\x00", r)
		} else {
			fmt.Fprintln(writer, r)
		}
	}

	return 0
}

// numToStr converts int to string
func numToStr(n int) string {
	return strconv.Itoa(n)
}
