			filtered = append(filtered, &RankedItem{
				item:  item,
				score: result.Score,
				start: result.Start,
				end:   result.End,
			})
		}
	}

	if t.opts.Sort && !t.pattern.empty {
		sort.SliceStable(filtered, func(i, j int) bool {
			return tiebreakCompare(filtered[i], filtered[j], t.opts.Tiebreak)
		})
	}

	t.filtered = filtered
}

func (t *Terminal) render() {
	tty := t.tty

	// Clear screen by moving cursor to home
	fmt.Fprint(tty, "\x1b[?25l") // hide cursor

	listHeight := t.height - 1 // reserve 1 line for prompt
	if listHeight < 1 {
		listHeight = 1
	}

	// Ensure selected is visible
	if t.selected >= t.offset+listHeight {
		t.offset = t.selected - listHeight + 1
	}
	if t.selected < t.offset {
		t.offset = t.selected
	}

	// Clear screen
	fmt.Fprint(tty, "\x1b[2J\x1b[H")

	reverse := t.opts.Layout == "reverse" || t.opts.Layout == "reverse-list"

	if reverse {
		// Render prompt first, then list below
		t.renderPrompt()
		fmt.Fprintln(tty)
		for i := t.offset; i < t.offset+listHeight && i < len(t.filtered); i++ {
			t.renderItem(i)
			if i < t.offset+listHeight-1 {
				fmt.Fprintln(tty)
			}
		}
	} else {
		// Default: list above, prompt below
		startRow := t.height - listHeight - 1
		if startRow < 0 {
			startRow = 0
		}

		// Print empty lines above
		for i := 0; i < startRow; i++ {
			fmt.Fprintln(tty)
		}

		for i := t.offset; i < t.offset+listHeight && i < len(t.filtered); i++ {
			t.renderItem(i)
			if i < t.offset+listHeight-1 {
				fmt.Fprintln(tty)
			}
		}

		// Fill remaining list area
		displayed := len(t.filtered) - t.offset
		if displayed > listHeight {
			displayed = listHeight
		}
		for i := displayed; i < listHeight; i++ {
			fmt.Fprintln(tty)
		}

		t.renderPrompt()
	}

	fmt.Fprint(tty, "\x1b[?25h") // show cursor
}

func (t *Terminal) renderItem(idx int) {
	item := t.filtered[idx].item
	text := getDisplayText(item, t.opts)

	isSelected := idx == t.selected
	isMulti := t.multiSelected[item.index]

	if t.opts.NoUnicode {
		if isMulti {
			fmt.Fprint(t.tty, ">")
		} else if isSelected {
			fmt.Fprint(t.tty, ">")
		} else {
			fmt.Fprint(t.tty, " ")
		}
	} else {
		if isMulti {
			fmt.Fprint(t.tty, "┃")
		} else if isSelected {
			fmt.Fprint(t.tty, "▌")
		} else {
			fmt.Fprint(t.tty, " ")
		}
	}

	if isSelected && !t.opts.NoBold {
		fmt.Fprint(t.tty, "\x1b[1m")
	}

	// Truncate to width
	runes := []rune(text)
	maxWidth := t.width - 2
	if maxWidth < 0 {
		maxWidth = 0
	}
	if len(runes) > maxWidth {
		runes = runes[:maxWidth]
	}
	fmt.Fprint(t.tty, string(runes))

	if isSelected && !t.opts.NoBold {
		fmt.Fprint(t.tty, "\x1b[0m")
	}
}

func (t *Terminal) renderPrompt() {
	info := ""
	if len(t.filtered) > 0 {
		info = fmt.Sprintf("%d/%d", len(t.filtered), len(t.input))
	} else {
		info = fmt.Sprintf("0/%d", len(t.input))
	}

	prompt := "> "
	if t.opts.Prompt != "" {
		prompt = t.opts.Prompt
	}

	queryStr := string(t.query)

	// Print info line
	fmt.Fprintf(t.tty, "  %s", info)
	fmt.Fprintln(t.tty)

	// Print prompt
	fmt.Fprintf(t.tty, "%s%s", prompt, queryStr)

	// Position cursor
	cursorPos := len([]rune(prompt)) + t.cursor + 1
	fmt.Fprintf(t.tty, "\x1b[%dG", cursorPos)
}

func (t *Terminal) clearScreen() {
	fmt.Fprint(t.tty, "\x1b[2J\x1b[H")
	fmt.Fprint(t.tty, "\x1b[?25h") // show cursor
}

// runInteractive runs fzf in interactive/TUI mode
func runInteractive(opts *Options) int {
	// Read input
	var items []*Item

	stdinReader := getInputReader(opts)
	reader := bufio.NewReader(stdinReader)
	index := 0

	if opts.ReadNul {
		var buf strings.Builder
		for {
			ch, err := reader.ReadByte()
			if err != nil {
				if buf.Len() > 0 {
					items = append(items, newItem(buf.String(), index))
					index++
				}
				break
			}
			if ch == 0 {
				items = append(items, newItem(buf.String(), index))
				index++
				buf.Reset()
			} else {
				buf.WriteByte(ch)
			}
		}
	} else {
		for {
			line, err := reader.ReadString('\n')
			line = strings.TrimRight(line, "\n\r")
			if line != "" {
				items = append(items, newItem(line, index))
				index++
			}
			if err != nil {
				break
			}
		}
	}

	// Apply --tac
	if opts.Tac {
		for i, j := 0, len(items)-1; i < j; i, j = i+1, j-1 {
			items[i], items[j] = items[j], items[i]
		}
	}

	// Apply --tail
	if opts.TailSize > 0 && len(items) > opts.TailSize {
		items = items[len(items)-opts.TailSize:]
	}

	// Extract header lines
	var headerItems []string
	if opts.HeaderLines > 0 && len(items) >= opts.HeaderLines {
		for i := 0; i < opts.HeaderLines; i++ {
			headerItems = append(headerItems, items[i].raw)
		}
		items = items[opts.HeaderLines:]
	}
	_ = headerItems

	// --select-1 and --exit-0 modes
	if opts.Select1 || opts.Exit0 {
		var filtered []*RankedItem
		slab := NewSlab()

		queryStr := opts.Query
		caseSensitive := opts.CaseSensitive == 1
		if opts.CaseSensitive == -1 {
			for _, r := range queryStr {
				if r >= 'A' && r <= 'Z' {
					caseSensitive = true
					break
				}
			}
		}
		pattern := buildPattern(queryStr, opts.Extended, opts.Exact, caseSensitive, opts.Normalize, opts.Algo)

		for _, item := range items {
			searchText := getSearchText(item, opts)
			searchRunes := []rune(searchText)

			if pattern.empty {
				filtered = append(filtered, &RankedItem{item: item})
				continue
			}

			result, ok := matchRunes(pattern, searchRunes, caseSensitive, opts.Normalize, opts.Algo, slab)
			if ok {
				filtered = append(filtered, &RankedItem{item: item, score: result.Score})
			}
		}

		if opts.Exit0 && len(filtered) == 0 {
			return 1
		}

		if opts.Select1 && len(filtered) == 1 {
			outputText := getOutputText(filtered[0].item, opts)
			writer := bufio.NewWriter(os.Stdout)
			if opts.PrintQuery {
				if opts.PrintNul {
					fmt.Fprintf(writer, "%s\x00", queryStr)
				} else {
					fmt.Fprintln(writer, queryStr)
				}
			}
			if opts.PrintNul {
				fmt.Fprintf(writer, "%s\x00", outputText)
			} else {
				fmt.Fprintln(writer, outputText)
			}
			writer.Flush()
			return 0
		}
	}

	// Check if we have a terminal to display the TUI
	// Check if stdin AND stdout are TTY
	if !isTerminal(os.Stdin) || !isTerminal(os.Stdout) {
		// We may be in a pipeline, but still need to show TUI on /dev/tty
	}

	// Run TUI
	term := newTerminal(opts, items)
	results, key, exitCode := term.Run()

	if exitCode != 0 {
		return exitCode
	}

	if len(results) == 0 {
		return 1
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	if opts.PrintQuery {
		if opts.PrintNul {
			fmt.Fprintf(writer, "%s\x00", opts.Query)
		} else {
			fmt.Fprintln(writer, opts.Query)
		}
	}

	if key != "" {
		if opts.PrintNul {
			fmt.Fprintf(writer, "%s\x00", key)
		} else {
			fmt.Fprintln(writer, key)
		}
	} else if len(term.expectKeys) > 0 {
		// Print empty key
		if opts.PrintNul {
			fmt.Fprintf(writer, "\x00")
		} else {
			fmt.Fprintln(writer)
		}
	}

	for _, r := range results {
		if opts.PrintNul {
			fmt.Fprintf(writer, "%s\x00", r)
		} else {
			fmt.Fprintln(writer, r)
		}
	}

	return 0
}

// numToStr converts int to string
func numToStr(n int) string {
	return strconv.Itoa(n)
}
