		pattern := []rune(test.pattern)

		r1, _ := src.FuzzyMatchV1(false, false, true, text, pattern, false, slab)
		r2, _ := src.FuzzyMatchV2(false, false, true, text, pattern, false, slab)

		v1OK := r1.Start >= 0
		v2OK := r2.Start >= 0

