# Let me also check a potential issue with the V2 algorithm when the traceback fails:
cat > /tmp/v2_check.go << 'EOF'
package main

import (
	"fmt"
	"fzf/src"
)

func main() {
	// Test cases where traceback might fail
	tests := []struct {
		text    string
		pattern string
	}{
		{"abcdef", "ace"},
		{"abcabc", "abc"},
		{"aabbcc", "abc"},
		{"foobar", "fbr"},
	}

	slab := src.NewSlab()
	for _, test := range tests {
		text := []rune(test.text)
		pattern := []rune(test.pattern)

		r1, _ := src.FuzzyMatchV1(false, false, true, text, pattern, false, slab)
		r2, _ := src.FuzzyMatchV2(false, false, true, text, pattern, false, slab)

		v1OK := r1.Start >= 0
		v2OK := r2.Start >= 0

		status := "OK"
		if v1OK != v2OK {
			status = "MISMATCH"
		}
		fmt.Printf("%s: '%s' in '%s': V1=[%d,%d]=%d, V2=[%d,%d]=%d\n",
			status, test.pattern, test.text,
			r1.Start, r1.End, r1.Score,
			r2.Start, r2.End, r2.Score)
	}
}
EOF
go run /tmp/v2_check.go 2>&1

